-- ============================================================================
-- v1355: Seed / sample data — ICT Delivery Overview and the registers it links
-- ============================================================================
-- Companion seed to v1354 (rule 18.2) for project SEED334-PRJ-08 (fictional Northbridge Bank
-- technology programme; vendor-neutral, rule 26). At least 10 records on each register the new
-- Delivery Overview form is built around:
--   Delivery Overview  (…-4000-a017-…)  10 records, every list field has 10 items
--   Workstreams        (…-4000-a018-…)  10 records
--   Technology Milestones (…-4000-a019-…) 10 records
--   Technology Roadmap (…-4000-a01a-…)  10 records
-- display_id is blank so Admin ID Generation assigns it. People are names in the text fields
-- (the user picker is still a text field). Linked-record fields store nothing: the Related tab
-- reads the workstream, milestone and roadmap rows for the same project.
-- Prerequisites: v949, v1321, v1324, v1354. Idempotent. Does not overwrite a row that already
-- exists (ON CONFLICT DO NOTHING).
-- ============================================================================

WITH proj AS (
  SELECT id, account_id FROM public.projects WHERE project_code = 'SEED334-PRJ-08' LIMIT 1
)
INSERT INTO public.local_register_records
  (id, register_id, display_id, title, description, status, field_values, account_id, project_id, record_project_id)
SELECT v.id::uuid, v.register_id::uuid, '', v.title, v.description, v.status, v.field_values::jsonb,
       p.account_id, p.id, p.id
FROM (VALUES
  ('00000000-0000-4000-a017-000000000001', '00000000-0000-4000-9003-000000000001', 'Customer and digital channels', 'Delivery of customer master data and the internet, mobile and branch channels for the Northbridge Bank technology programme. Owner: Amina Diallo.', 'in_delivery', $j${"delivery_lead":"Amina Diallo","business_owner":"Nomvula Khumalo","delivery_type":"replacement","delivery_approach":"hybrid","current_phase":"build","start_date":"2026-04-06","target_go_live":"2027-04-12","executive_sponsor":"Grace Moyo","technical_lead":"Ravi Pillai","governance_forum":"Channels steering group","reporting_cadence":"weekly","escalation_path":"Delivery lead raises an amber item at the weekly channels steering group. A red item, or any slip to the April 2027 go-live, goes to the executive sponsor the same day.","in_scope":"Retail and SME customer master\nCorporate customer master from the second legacy instance\nInternet banking registration\nMobile banking registration\nBranch teller customer search\nContact centre customer view\nStatement and alert preferences\nMandate and signature images\nCustomer number cross-reference\nChannel entitlement after go-live","out_of_scope":"Card plastic personalisation\nMarketing campaign tool\nLoyalty scheme\nInsurance product origination\nWealth advisory portal\nStaff intranet\nSupplier portal\nRecruitment system\nPayroll\nGeneral ledger close","success_criteria":"Every active customer has one surviving customer number\nAddress completeness at or above 85%\nInternet and mobile users can sign in on day one\nDuplicate customers reduced below 1%\nMandate images linked to the surviving customer\nBranch search returns the customer in under 3 seconds\nNo customer advice sent during the load\nChannel entitlements match the recertified list\nAlternate keys kept for the old customer numbers\nBusiness data owner signs off the customer population","assumptions":"Both legacy instances are profiled before Mock 2\nThe surviving record is the one with the most complete KYC data\nCustomers accept a new customer number where numbers clash\nBranch staff are trained before the dress rehearsal\nStatement templates are approved by the business\nThe document store can supply images for the load\nIdentity documents already scanned stay valid\nContact centre scripts are rewritten before UAT\nNo new customer products are launched in the freeze week\nThe target customer number is 8 digits","constraints":"Customer numbers must be unique across both legacy instances\nKYC fields are mandatory before a customer can be loaded\nAddress completeness target is 85%\nImages must be linked before the channel is opened\nThe load window is the weekend of 10–12 April 2027\nNo marketing mail is sent from the load\nPersonal data stays in the bank residency region\nBranch capture stops at the freeze\nOld numbers are kept for seven years\nThe channel cutover is the same weekend as the financial load","capabilities":"Single customer view\nCustomer deduplication\nInternet banking sign-in\nMobile banking sign-in\nBranch customer search\nContact centre desktop\nStatement preferences\nAlert preferences\nMandate viewing\nCustomer number cross-reference","systems_in_scope":"Legacy core – retail and SME instance\nLegacy core – corporate instance\nInternet banking\nMobile banking\nBranch teller\nContact centre desktop\nDocument imaging system\nCustomer due diligence repository\nDigital banking user store\nTarget customer master","environments_in_scope":["development","test","sit","uat"],"business_change_impact":"Branch staff stop capturing customers in the legacy core and use the target platform. Customers re-register for internet and mobile banking where their customer number changes. Statements and alerts move to the new templates.","overall_rag":"amber","schedule_rag":"amber","scope_rag":"green","quality_rag":"green","cost_rag":"amber","headline":"Internet and mobile registration is in build. Address completeness is still short of the 85% target and is the main threat to the static-data window.","last_review_date":"2026-11-02","next_review_date":"2026-11-16","key_dependencies":"Customer deduplication rules signed off\nKYC repository extract granted\nDocument image storage decision\nTarget customer products configured\n8-digit numbering agreed\nStatement templates approved\nContact centre trained\nBranch freeze communications sent\nMock 2 static load passed\nChannel entitlements recertified","key_risks":"Address completeness stays under 85%\nDuplicate customers are merged onto the wrong survivor\nImage volume slips the static window\nCustomers cannot sign in on day one\nOld customer numbers are dropped\nBranch staff keep using the legacy screens\nStatement templates are late\nKYC extract access is still only requested\nPersonal data leaves the agreed region\nChannel and financial cutovers fall on different weekends","key_issues":"Address completeness measured at 82% after Mock 1\n23,400 customers exist in both legacy instances\n4,150 customers have more than one number in a single instance\nImage storage location is not decided\nKYC extract access is requested, not yet granted\nContact centre scripts are still the legacy wording\nTwo statement templates are awaiting brand approval\nBranch champions are not named in 12 branches\nMobile registration test users were not refreshed after Mock 1\nCustomer advice suppression was missed in an early SIT load","decisions_needed":"Confirm the survivor rule for duplicate customers\nDecide image storage: file store or database\nApprove the two outstanding statement templates\nName a champion in every branch\nConfirm KYC extract access by 30 November 2026\nAgree the customer communication for changed numbers\nChoose the contact centre go-live script\nConfirm advice suppression is on the pre-migration checklist\nAccept the 8-digit customer number standard\nConfirm channel cutover is the same weekend as the financial load","delivery_team":"Delivery lead\tAmina Diallo\nBusiness owner\tNomvula Khumalo\nExecutive sponsor\tGrace Moyo\nTechnical lead\tRavi Pillai\nData analyst\tPriya Naidoo\nChannel analyst\tBrian Otieno\nTest lead\tCatherine Mwangi\nTraining lead\tLinda Zhou\nSecurity partner\tNadia Rahman\nChange lead\tDaniel Okafor","suppliers":"Implementation partner – channels\nData migration partner\nTesting partner\nDocument management provider\nIdentity verification service\nTraining partner\nService desk partner\nBranch communications partner\nStatement composition provider\nContact centre tooling partner","approved_budget":4800000,"forecast_to_complete":5100000,"expected_benefits":"One customer number for service and channels\nFewer duplicate records for staff to reconcile\nCustomers keep digital access on day one\nFaster branch and contact centre search\nCleaner KYC for ongoing due diligence\nLess manual repair after go-live\nA single place to turn alerts on or off\nOld numbers remain searchable\nLower cost of maintaining two customer masters\nA signed customer population for the financial load"}$j$),
  ('00000000-0000-4000-a017-000000000002', '00000000-0000-4000-9003-000000000001', 'Payments and transfers', 'Delivery of domestic payments, standing orders and internal transfers onto the target platform. Owner: Ahmed Hassan.', 'in_delivery', $j${"delivery_lead":"Ahmed Hassan","business_owner":"Catherine Mwangi","delivery_type":"replacement","delivery_approach":"iterative","current_phase":"test","start_date":"2026-05-04","target_go_live":"2027-04-12","executive_sponsor":"Daniel Okafor","technical_lead":"Brian Otieno","governance_forum":"Payments working group","reporting_cadence":"weekly","escalation_path":"The payments working group clears ambers weekly. A failed settlement test or a scheme-window slip is escalated to the executive sponsor before the next scheme cycle.","in_scope":"Domestic credit transfers\nInternal account transfers\nStanding orders\nFuture-dated payments\nPayment limits by channel\nSettlement timetable\nUnpaid and returned payments\nPayment repair queue\nScheme cut-off calendar\nPayment reference cross-reference","out_of_scope":"Card authorisation\nATM cash\nCheque clearing replacement\nCross-border correspondent banking rebuild\nCash-in-transit\nPoint of sale acquiring\nMerchant settlement\nCrypto assets\nOpen-banking directory membership\nPayroll file payments","success_criteria":"Every active standing order is recreated before go-live\nSettlement totals agree to the cent\nReturned payments land on the repair queue\nChannel limits match the signed matrix\nNo duplicate payment on the cutover weekend\nCut-off calendar loaded for the next 18 months\nOperations can repair a payment without the legacy core\nCustomer payment references are preserved\nScheme window is met on the first business day\nBusiness owner signs off the payment population","assumptions":"The scheme timetable does not change before go-live\nStanding orders are recreated, not replayed from history\nBoth legacy instances use the same value-date rule\nPayment limits are signed by the business before UAT\nThe repair queue is staffed for hypercare\nTest scheme membership stays available through dress rehearsal\nFuture-dated payments inside the freeze are cancelled and re-entered\nCustomer accounts exist before payments are loaded\nNo new payment type is added after design approval\nThe first business day is a normal scheme day","constraints":"Scheme cut-off cannot move\nSettlement must balance on the night\nStanding orders with an end date in the past are excluded\nDual control stays on the repair queue\nPayment files are not accepted during the freeze\nLimits cannot exceed the signed matrix\nThe load finishes before the first scheme window\nPersonal payment references are not printed on operations reports\nReturned items are visible the same morning\nHypercare cover runs for four weeks","capabilities":"Domestic credit transfer\nInternal transfer\nStanding order booking\nFuture-dated payment\nPayment limits\nSettlement\nReturns and unpaids\nRepair queue\nCut-off calendar\nPayment enquiry","systems_in_scope":"Legacy core – both instances\nTarget payments engine\nScheme gateway\nChannel payment screens\nStanding order store\nRepair workflow\nSettlement reports\nLimits service\nCustomer notifications\nOperations dashboard","environments_in_scope":["development","test","sit","uat","pre_production"],"business_change_impact":"Customers and branches initiate payments in the target platform. Standing orders are recreated rather than replayed. Operations follow the new settlement timetable.","overall_rag":"green","schedule_rag":"green","scope_rag":"green","quality_rag":"amber","cost_rag":"green","headline":"Domestic credit transfers are in system test. The standing-order remapping from both legacy instances is the open quality item.","last_review_date":"2026-11-04","next_review_date":"2026-11-18","key_dependencies":"Customer and account numbers mapped\nScheme gateway certificate renewed\nLimit matrix signed\nSettlement accounts configured\nCut-off calendar agreed with operations\nRepair roles assigned\nUAT payment accounts funded\nNotification templates approved\nMock 2 payment file compared\nHypercare roster published","key_risks":"Standing orders are duplicated across the two instances\nScheme certificate expires before dress rehearsal\nSettlement does not balance on the night\nRepair queue is understaffed on day one\nFuture-dated payments are lost in the freeze\nChannel limits are looser than the signed matrix\nA scheme change lands inside the freeze\nCustomer notifications fire during the load\nValue dates shift by a day\nThe first business day is a scheme holiday","key_issues":"1,180 standing orders exist in both instances\nScheme certificate renewal is with the gateway team\nTwo limit bands are still in draft\nRepair training is booked but not delivered\nNotification suppression failed once in SIT\nCut-off calendar stops at December 2027 and must be extended\nUAT funding for payment accounts is not yet approved\nA test file used production account numbers\nReturned-item report layout is not signed\nHypercare roster has two unnamed night shifts","decisions_needed":"Confirm standing orders are recreated rather than replayed\nExtend the cut-off calendar through October 2028\nApprove UAT funding for payment accounts\nName the two night-shift hypercare leads\nSign the remaining limit bands\nConfirm notification suppression on the checklist\nAccept the returned-item report layout\nChoose the survivor standing order where both instances hold one\nConfirm the first business day scheme window\nAgree dual control on the repair queue","delivery_team":"Delivery lead\tAhmed Hassan\nBusiness owner\tCatherine Mwangi\nExecutive sponsor\tDaniel Okafor\nTechnical lead\tBrian Otieno\nSettlement analyst\tOlivia Banda\nTest lead\tPriya Naidoo\nOperations lead\tLinda Zhou\nSecurity partner\tNadia Rahman\nChange lead\tAmina Diallo\nChannel analyst\tRavi Pillai","suppliers":"Implementation partner – payments\nScheme gateway provider\nTesting partner\nData migration partner\nTraining partner\nService desk partner\nNotification provider\nSecurity testing partner\nReport design partner\nHypercare staffing partner","approved_budget":3100000,"forecast_to_complete":3050000,"expected_benefits":"One payment engine instead of two cores\nStanding orders survive the cutover\nFaster repair of returned payments\nSettlement that operations can explain\nClearer channel limits\nLess manual standing-order repair\nA calendar operations can plan to\nCustomer references preserved on enquiries\nLower run cost after decommission\nA signed payment population for go-live"}$j$),
  ('00000000-0000-4000-a017-000000000003', '00000000-0000-4000-9003-000000000001', 'Lending, limits and collateral', 'Delivery of loans, limits and collateral, including overdue bills and the expired-limit rule. Owner: Joy Akinyi.', 'in_delivery', $j${"delivery_lead":"Joy Akinyi","business_owner":"Daniel Okafor","delivery_type":"replacement","delivery_approach":"structured","current_phase":"design","start_date":"2026-05-18","target_go_live":"2027-04-12","executive_sponsor":"Grace Moyo","technical_lead":"Priya Naidoo","governance_forum":"Credit design authority","reporting_cadence":"fortnightly","escalation_path":"A red schedule item is raised at the credit design authority and copied to the executive sponsor. A product rule that changes a customer balance is not applied until credit and finance both agree.","in_scope":"Retail loan arrangements\nCorporate loan arrangements\nOverdue and due bills\nAccrued interest on loans\nLimit records\nExpired limits still linked to a contract\nCollateral rights\nCollateral items\nRepayment account selection\nCredit enquiry","out_of_scope":"New scorecard build\nDebt collection agency files\nSecuritisation\nSyndicated loan agency\nTrade finance instruments\nTreasury dealing\nCard instalment plans\nStaff loans policy rewrite\nProvisioning model rebuild\nRegulatory capital calculator","success_criteria":"Every live loan has an arrangement, a balance and a schedule\nAgeing continues from the legacy past-due date\nExpired limits follow the signed rule\nCollateral is linked before the loan is loaded\nOne repayment account per customer per currency\nTake-over accounts return to zero\nCredit can enquire without the legacy core\nAccrual is not double-counted\nMapping sheet is approved before Mock 2\nCredit signs the loan population","assumptions":"Schedules are regenerated from the migrated frequency\nThe expired-limit rule is expiry plus one day, with the original date kept\nOne liquidation account is allowed per customer per currency\nCollateral rights load before collateral items\nPast-due date becomes the bill date\nNo new loan product is launched after design approval\nCredit officers are trained before UAT\nTake-over accounts are configured by finance\nBoth instances use the same accrual convention\nLimits keep an alternate key","constraints":"A loan cannot load before its customer and account\nCollateral cannot load before its right\nAgeing must not reset to zero\nExpired limits cannot be dropped while a contract is live\nTake-over accounts must be zero after reconciliation\nDual control remains on limit changes\nThe design authority meets every two weeks\nPersonal income data is not copied to operations reports\nMock 2 cannot start with the mapping sheet in draft\nThe April 2027 weekend is fixed","capabilities":"Loan arrangement\nBalance and accrual capture\nBill and ageing\nLimit maintenance\nExpired-limit rule\nCollateral right\nCollateral item\nRepayment account\nCredit enquiry\nTake-over reconciliation","systems_in_scope":"Legacy core – both instances\nTarget lending module\nLimits service\nCollateral register\nCredit workflow\nTake-over accounts\nDocument imaging system\nCustomer master\nRepayment account service\nCredit reporting","environments_in_scope":["development","test","sit"],"business_change_impact":"Credit officers originate and service loans in the target platform. Expired limits are renewed or adjusted under the agreed rule. Collateral is linked before the loan is loaded.","overall_rag":"amber","schedule_rag":"red","scope_rag":"amber","quality_rag":"amber","cost_rag":"amber","headline":"Schedule design is behind. Expired limits that still secure a live contract are not yet decided, and that decision blocks the mapping sheet.","last_review_date":"2026-10-28","next_review_date":"2026-11-11","key_dependencies":"Customer numbers mapped\nExpired-limit rule signed by credit\nRepayment account rule signed\nCollateral identifier format agreed\nTake-over accounts opened\nMapping sheet out of draft\nCredit training plan approved\nMock 2 dates held\nFinance agrees the accrual treatment\nDocument links for collateral schedules","key_risks":"Schedule design slips Mock 2\nExpired limits are dropped and a contract is left unsecured\nAgeing resets and collections mis-prioritise\nTake-over accounts do not return to zero\nCollateral loads before its right and is rejected\nTwo repayment accounts remain and the load fails\nAccrual is counted twice\nCredit training is after UAT starts\nThe mapping sheet stays in draft\nA product rule changes a customer balance without finance agreement","key_issues":"Schedule design is two weeks behind the plan\n2,180 expired limits are not yet reviewed\n8,900 loans still have more than one repayment account\nCollateral mapping is approved but the load order is not rehearsed\nTake-over account for loans is not opened\nAccrual treatment is with finance\nCredit training dates clash with branch training\nMapping sheet status is still draft\nOne limit band has no owner\nMock 2 entry criteria do not mention the mapping sheet","decisions_needed":"Sign the expired-limit rule\nOpen the loan take-over account\nConfirm one repayment account per customer per currency\nName an owner for the remaining limit band\nMove credit training ahead of UAT\nAdd the mapping sheet to the Mock 2 entry criteria\nAgree accrual treatment with finance\nRehearse collateral load order\nAccept regenerated schedules\nConfirm ageing uses the legacy past-due date","delivery_team":"Delivery lead\tJoy Akinyi\nBusiness owner\tDaniel Okafor\nExecutive sponsor\tGrace Moyo\nTechnical lead\tPriya Naidoo\nCredit analyst\tAhmed Hassan\nCollateral analyst\tLinda Zhou\nFinance partner\tOlivia Banda\nTest lead\tCatherine Mwangi\nData analyst\tAmina Diallo\nChange lead\tBrian Otieno","suppliers":"Implementation partner – lending\nData migration partner\nTesting partner\nCollateral valuation data provider\nTraining partner\nService desk partner\nReport design partner\nSecurity testing partner\nDocument management provider\nCredit workflow partner","approved_budget":5400000,"forecast_to_complete":5750000,"expected_benefits":"One lending record instead of two cores\nAgeing that collections can trust\nLimits that still secure live contracts\nCollateral linked to the right customer\nLess manual schedule repair\nA take-over that finance can explain\nCredit officers leave the legacy screens\nClearer repayment instructions\nA signed loan population\nLower run cost after decommission"}$j$),
  ('00000000-0000-4000-a017-000000000004', '00000000-0000-4000-9003-000000000001', 'Deposits and accounts', 'Delivery of current accounts, savings and term deposits, including balances and accruals. Owner: Catherine Mwangi.', 'published', $j${"delivery_lead":"Catherine Mwangi","business_owner":"Nomvula Khumalo","delivery_type":"replacement","delivery_approach":"hybrid","current_phase":"test","start_date":"2026-04-20","target_go_live":"2027-04-12","executive_sponsor":"Olivia Banda","technical_lead":"Brian Otieno","governance_forum":"Deposits product forum","reporting_cadence":"fortnightly","escalation_path":"The product forum owns ambers. A balance that will not reconcile, or a product mapping change after approval, goes to the executive sponsor and finance together.","in_scope":"Current accounts\nSavings accounts\nTerm deposits\nDeposit balances and accruals\nDormant accounts over five years\nMatured deposits that still hold a balance\nAccount restrictions\nStatement frequency\nAlternate account keys for the second instance\nAccount enquiry","out_of_scope":"Safe custody\nNew savings product launch\nPrize-linked savings\nChildren account campaign\nBrokerage cash accounts\nTrust accounting\nMulti-currency wallet\nInterest rate change programme\nBranch cash holdings\nGeneral ledger rebuild","success_criteria":"Every open account has a product, a balance and an owner\nInstance 2 account numbers are kept as alternate keys\nDormant accounts over five years are closed or transferred\nMatured deposits no longer carry a balance at the freeze\nRestrictions match the legacy narrative\nStatement frequency is remapped\nBalances agree by product and currency\nAccrual value date is the migration date\nCustomers can enquire on day one\nProduct owners sign the population","assumptions":"Three legacy current-account products become one target product\nInstance 2 numbers become 10 digits with a check digit\nDormant means no customer-initiated transaction for five years\nUnclaimed balances move under the existing regulation\nMatured deposits are paid out or rolled, not migrated as running\nStatement frequency is remapped only where it is not the default\nRestrictions carry their narrative\nFinance owns the balance control total\nNo account is closed in the week before go-live\nThe target allows the signed product set only","constraints":"No account closures in the week before go-live\nA zero-balance account marked for closure is excluded\nAlternate keys are mandatory for instance 2\nAccrual value date cannot be the original accrual date\nProduct mapping cannot change after Mock 2 without a new approval\nDormant processing finishes in November 2026\nControl totals come from the trial balance\nPersonal balances are not listed on the operations dashboard\nThe freeze starts at the final close of business\nEnquiry must work without the legacy core","capabilities":"Current account\nSavings account\nTerm deposit\nBalance and accrual capture\nRestriction\nStatement frequency\nAlternate account key\nDormant processing\nAccount enquiry\nBalance reconciliation","systems_in_scope":"Legacy core – both instances\nTarget accounts module\nTarget deposits module\nRestrictions service\nStatement engine\nTake-over accounts\nCustomer master\nFinance trial balance\nBranch screens\nEnquiry service","environments_in_scope":["development","test","sit","uat"],"business_change_impact":"Customers see current, savings and deposit accounts in the target platform. Matured deposits are paid out or rolled before the freeze. Dormant accounts follow the unclaimed-balance rule.","overall_rag":"green","schedule_rag":"green","scope_rag":"green","quality_rag":"green","cost_rag":"green","headline":"Account and deposit mapping is approved. Matured deposits that still carry a balance remain the cleansing item before the freeze.","last_review_date":"2026-11-03","next_review_date":"2026-11-17","key_dependencies":"Product mapping approved\n10-digit account standard agreed\nDormant population identified\nMatured-deposit population identified\nTake-over accounts opened\nStatement engine configured\nRestriction code map signed\nFinance control-total owner named\nMock 2 account file compared\nBranch freeze notice drafted","key_risks":"Matured deposits are still open at the freeze\nDormant processing slips past November\nAccount numbers clash across the two instances\nA restriction narrative is dropped\nStatement frequency defaults incorrectly\nTake-over does not return to zero\nStaff close accounts in the freeze week\nProduct mapping is reopened after Mock 2\nAccrual is double-counted\nEnquiry is slow on the first morning","key_issues":"1,320 matured deposits still carry a balance\n18,700 dormant accounts are identified and not yet processed\nRestriction narratives are mapped but not sample-checked\nStatement frequency remapping has not started\nTake-over account for deposits is open\nBranch freeze notice is in draft\nTwo product codes remain mapped to a retired target product\nSample of alternate keys passed\nEnquiry test was not run at branch volume\nNovember dormant workshop is not on the branch calendar","decisions_needed":"Confirm matured deposits are paid out or rolled, not migrated as running\nPut the dormant workshop on the November branch calendar\nRetire the two product codes that point at a retired product\nStart statement-frequency remapping\nSample-check restriction narratives\nApprove the branch freeze notice\nKeep the rule of no closures in the week before go-live\nConfirm finance owns the balance control total\nAccept 10-digit numbers with a check digit\nSchedule an enquiry test at branch volume","delivery_team":"Delivery lead\tCatherine Mwangi\nBusiness owner\tNomvula Khumalo\nExecutive sponsor\tOlivia Banda\nTechnical lead\tBrian Otieno\nProduct analyst\tAmina Diallo\nFinance partner\tDaniel Okafor\nTest lead\tPriya Naidoo\nOperations lead\tLinda Zhou\nChange lead\tAhmed Hassan\nData analyst\tJoy Akinyi","suppliers":"Implementation partner – deposits\nData migration partner\nTesting partner\nStatement composition provider\nTraining partner\nService desk partner\nReport design partner\nBranch communications partner\nSecurity testing partner\nDocument management provider","approved_budget":2600000,"forecast_to_complete":2480000,"expected_benefits":"One account record for the customer\nDeposits that are actually running on day one\nDormant balances treated under the existing rule\nRestrictions staff can read\nStatements on the frequency the customer expects\nOld account numbers still searchable\nFinance can tie balances to the trial balance\nLess repair of matured deposits after go-live\nBranches stop using two cores\nA signed account population"}$j$),
  ('00000000-0000-4000-a017-000000000005', '00000000-0000-4000-9003-000000000001', 'Data migration and quality', 'Cross-cutting delivery of extraction, cleansing, transformation, mock runs and reconciliation for the programme. Owner: Priya Naidoo.', 'in_delivery', $j${"delivery_lead":"Priya Naidoo","business_owner":"Amina Diallo","delivery_type":"migration","delivery_approach":"structured","current_phase":"test","start_date":"2026-03-02","target_go_live":"2027-04-12","executive_sponsor":"Olivia Banda","technical_lead":"Brian Otieno","governance_forum":"Data migration design authority","reporting_cadence":"weekly","escalation_path":"The design authority meets weekly. A control total that does not balance, or a missed mock entry criterion, is raised to the executive sponsor the same day.","in_scope":"Source profiling\nExtraction from both legacy instances\nCleansing at source\nTransformation rules\nMock runs\nDress rehearsal\nReconciliation by product and currency\nTake-over and suspense accounts\nControl totals\nBusiness sign-off of each population","out_of_scope":"Building the target platform\nCard scheme certification\nGeneral ledger replacement\nStaff identity directory rebuild\nA new data warehouse\nHistorical transaction archive design\nCustomer communication creative\nBranch refurbishment\nVendor contract negotiation\nRegulatory return redesign","success_criteria":"Mock 2 static data loads inside the window\nMock 3 financial data reconciles\nDress rehearsal finishes with no severity-1 defect open\nTake-over and suspense accounts are zero\nEach population has a named data owner\nControl totals tie to the trial balance\nExtracts follow the agreed file layout\nCleansing backlog is clear before the freeze\nRollback is rehearsed\nThe go/no-go pack is complete","assumptions":"Three mock runs and one dress rehearsal are enough\nCleansing is done in the source, not in the load\nThe file layout is plain text, one record per line\nDates travel as YYYYMMDD\nControl totals come from the final close of business\nData owners can halt a load\nThe legacy cores can be frozen\nTake-over accounts are opened before Mock 2\nNo new source is added after Mock 2\nHistory beyond the agreed scope is archived, not loaded","constraints":"The April 2027 weekend is fixed\nPersonal data stays in the residency region\nA population cannot load before its predecessor\nSeverity-1 defects block the next mock\nTake-over accounts must finish at zero\nExtracts are taken after close of business\nThe freeze allows no new business\nSign-off is by the data owner, not the project alone\nFile layout cannot change after Mock 2 without approval\nEvidence is kept for the retention period","capabilities":"Profiling\nExtraction\nCleansing tracking\nTransformation\nMock run\nReconciliation\nControl totals\nTake-over accounting\nDefect tracking\nData-owner sign-off","systems_in_scope":"Legacy core – both instances\nDocument imaging system\nFinance and general ledger system\nCustomer due diligence repository\nMigration tool\nTarget platform\nTake-over accounts\nReconciliation workbook\nDefect register\nSign-off store","environments_in_scope":["development","test","sit","uat"],"business_change_impact":"Business data owners cleanse at source and sign their population. Operations run the freeze, the load and the reconciliation, then stop using the legacy cores for new business.","overall_rag":"amber","schedule_rag":"amber","scope_rag":"green","quality_rag":"amber","cost_rag":"amber","headline":"Mock 1 has run. Mock 2 static data is the next proof. Take-over accounts were not at zero after Mock 1 and remain the reconciliation gap.","last_review_date":"2026-11-06","next_review_date":"2026-11-13","key_dependencies":"Source access granted\nFile layout signed\nTake-over accounts opened\nData owners named\nMock calendar held\nTrial balance owner named\nDefect severity scale agreed\nRollback steps written\nDress rehearsal environment booked\nRetention schedule agreed with records management","key_risks":"Take-over accounts do not return to zero\nA source access request is still open at Mock 2\nCleansing slips past the freeze\nThe file layout changes late\nA severity-1 defect is found in dress rehearsal\nControl totals are taken before close of business\nData owners are unavailable to sign\nThe mock window overruns\nPersonal data is copied into a shared workbook\nRollback is untested","key_issues":"Mock 1 take-over accounts were not at zero\nMock 1 overran by 9 hours and was rerun on 3–4 October 2026\nKYC extract access is still requested\nImage storage decision is open\nTwo data-owner sign-off forms are not issued\nA shared workbook held a customer sample longer than agreed\nFile layout examples are missing the multi-value case\nDress rehearsal environment is not booked\nRollback steps are an outline\nThe defect scale is agreed but not on the mock entry checklist","decisions_needed":"Keep three mocks plus one dress rehearsal\nBook the dress rehearsal environment\nIssue the remaining data-owner sign-off forms\nAdd the defect scale to the mock entry checklist\nRemove the customer sample from the shared workbook\nConfirm extracts are after close of business\nHold the file layout after Mock 2\nName the trial balance owner\nWrite rollback as steps, not an outline\nConfirm cleansing stays in the source","delivery_team":"Delivery lead\tPriya Naidoo\nBusiness data owner\tAmina Diallo\nExecutive sponsor\tOlivia Banda\nTechnical lead\tBrian Otieno\nReconciliation lead\tOlivia Banda\nFinance partner\tDaniel Okafor\nTest lead\tCatherine Mwangi\nQuality lead\tNadia Rahman\nChange lead\tLinda Zhou\nMigration analyst\tAhmed Hassan","suppliers":"Data migration partner\nImplementation partner\nTesting partner\nReconciliation tooling partner\nDocument management provider\nTraining partner\nService desk partner\nAudit support partner\nEnvironment provider\nRecords management partner","approved_budget":6100000,"forecast_to_complete":6400000,"expected_benefits":"A load the bank can explain to audit\nControl totals that match the trial balance\nLess manual repair after go-live\nData owners who have signed their population\nA rehearsed rollback\nOne file layout for every source\nEvidence for the retention period\nFewer duplicate customers reaching the target\nA freeze the branches understand\nA go/no-go pack that is complete"}$j$),
  ('00000000-0000-4000-a017-000000000006', '00000000-0000-4000-9003-000000000001', 'Integration and interfaces', 'Delivery of the interfaces the target platform needs from channels, cards, finance, documents and the user store. Owner: Brian Otieno.', 'in_delivery', $j${"delivery_lead":"Brian Otieno","business_owner":"Ravi Pillai","delivery_type":"integration","delivery_approach":"iterative","current_phase":"build","start_date":"2026-06-01","target_go_live":"2027-04-12","executive_sponsor":"Daniel Okafor","technical_lead":"Ravi Pillai","governance_forum":"Integration design authority","reporting_cadence":"weekly","escalation_path":"The integration authority owns ambers. An interface that misses SIT entry is escalated to the executive sponsor with a revised slot before the next weekly meeting.","in_scope":"Internet banking interface\nMobile banking interface\nBranch teller interface\nContact centre interface\nCard status cross-check\nDocument image retrieval\nFinance trial-balance file\nDigital user-store link\nNotification dispatch\nInterface monitoring and repair","out_of_scope":"A new integration platform product selection\nOpen-banking directory build\nCard scheme certification\nATM switch replacement\nPoint of sale acquiring\nMarket data feed\nPayroll interface\nBuilding access systems\nA general enterprise service bus rebuild\nPartner onboarding portal","success_criteria":"Each in-scope interface has a contract, a test and an owner\nFailed messages are visible on one dashboard\nCard status cross-check agrees active cards\nTrial-balance file balances before it is used\nImage retrieval works for a mandate\nChannels no longer call the legacy cores after go-live\nRepair time for a failed message is under 30 minutes\nCertificates are valid through hypercare\nNo silent message loss in dress rehearsal\nInterface owners sign readiness","assumptions":"Existing channels are reused and pointed at the target\nThe card system is not migrated; only status is cross-checked\nThe finance system stays and sends a file\nCertificates can be renewed without a scheme change\nOne dashboard covers every in-scope interface\nMessage replay is allowed once\nOwners are named before SIT\nTest data is synthetic except for the dress rehearsal\nThe legacy cores stay up read-only after go-live\nNo new interface is added after design approval","constraints":"SIT entry dates are fixed on the integration plan\nA missing certificate blocks that interface\nCard numbers are not stored on the dashboard\nThe trial-balance file is after close of business\nReplay cannot create a second payment\nPersonal images are retrieved only for an entitled user\nThe dress rehearsal uses the production-like path\nRepair is dual-controlled for payments\nMonitoring alerts reach the duty roster\nHypercare keeps the same dashboard","capabilities":"Channel interface\nCard status cross-check\nImage retrieval\nTrial-balance file\nUser-store link\nNotification dispatch\nMessage repair\nInterface monitoring\nCertificate management\nReadiness sign-off","systems_in_scope":"Target platform\nInternet banking\nMobile banking\nBranch teller\nContact centre\nCard management platform\nDocument imaging system\nFinance system\nDigital user store\nNotification service","environments_in_scope":["development","test","sit","uat"],"business_change_impact":"Channels and internal systems call the target platform instead of the legacy cores. Operations monitor the new interface dashboard. Failed messages are repaired in the new queue.","overall_rag":"amber","schedule_rag":"amber","scope_rag":"green","quality_rag":"amber","cost_rag":"green","headline":"Twelve interfaces are in build. The card status cross-check and the finance trial-balance file are the two that do not yet have a test slot.","last_review_date":"2026-11-05","next_review_date":"2026-11-19","key_dependencies":"Interface contracts approved\nSIT slots booked\nCertificates inventoried\nDashboard built\nRepair roles assigned\nCard status file sample received\nTrial-balance file sample received\nImage retrieval entitlement model agreed\nDuty roster published\nDress rehearsal path agreed","key_risks":"Two interfaces miss their SIT slot\nA certificate expires in hypercare\nCard status file is late\nTrial-balance file does not balance\nReplay creates a duplicate payment\nThe dashboard misses a silent failure\nImage retrieval is too slow at the branch\nA channel still points at the legacy core\nRepair roles are not staffed at night\nA new interface is added after design approval","key_issues":"Card status and trial-balance have no SIT slot\nCertificate inventory is incomplete\nDashboard shows four of twelve interfaces\nRepair role for payments is not named\nImage retrieval test used a synthetic mandate only\nOne channel configuration still has the legacy address\nDuty roster stops at go-live and not hypercare\nMessage sample for notifications is unsigned\nReplay test has not been run\nThe interface register and this delivery use different names for two flows","decisions_needed":"Book SIT slots for card status and the trial-balance file\nFinish the certificate inventory\nName the payments repair role\nExtend the duty roster through hypercare\nRemove the remaining legacy channel address\nAlign the two flow names with the interface register\nSign the notification message sample\nRun the replay test before SIT exit\nAgree the image entitlement model\nHold the interface list after design approval","delivery_team":"Delivery lead\tBrian Otieno\nBusiness owner\tRavi Pillai\nExecutive sponsor\tDaniel Okafor\nTechnical lead\tRavi Pillai\nInterface analyst\tPriya Naidoo\nTest lead\tCatherine Mwangi\nSecurity partner\tNadia Rahman\nOperations lead\tLinda Zhou\nFinance partner\tOlivia Banda\nChange lead\tAmina Diallo","suppliers":"Implementation partner – integration\nTesting partner\nCertificate provider\nCard management provider\nNotification provider\nDocument management provider\nService desk partner\nSecurity testing partner\nMonitoring tooling partner\nTraining partner","approved_budget":3700000,"forecast_to_complete":3900000,"expected_benefits":"Channels call one platform\nFailed messages are seen, not lost\nCard status stays consistent\nFinance receives a file it can tie\nBranches can see a mandate\nLess overnight manual checking\nCertificates are tracked\nA readiness sign-off per interface\nRepair in one queue\nA cleaner decommission of the legacy cores"}$j$),
  ('00000000-0000-4000-a017-000000000007', '00000000-0000-4000-9003-000000000001', 'Cybersecurity and access', 'Delivery of user access, recertification and the security controls required before go-live. Currently on hold. Owner: Nadia Rahman.', 'on_hold', $j${"delivery_lead":"Nadia Rahman","business_owner":"Daniel Okafor","delivery_type":"enhancement","delivery_approach":"hybrid","current_phase":"design","start_date":"2026-06-15","target_go_live":"2027-04-12","executive_sponsor":"Grace Moyo","technical_lead":"Nadia Rahman","governance_forum":"Security design authority","reporting_cadence":"fortnightly","escalation_path":"The hold is already with the executive sponsor. The authority does not restart build until recertification has a date and an owner.","in_scope":"Bank user profiles\nUser groups and roles\nLine-manager recertification\nPrivileged access\nJoiner, mover and leaver handling\nAuthentication for staff\nEntitlement after go-live\nSecurity logging\nAccess evidence for audit\nHypercare access revocation","out_of_scope":"Customer authentication redesign\nA new identity product selection\nBuilding access\nCard PIN platform\nEndpoint replacement\nSecurity operations centre build\nPenetration test of unrelated systems\nData loss prevention product selection\nSupplier security assessments outside this programme\nStaff background checks","success_criteria":"Every loaded user has a recertified entitlement\nLeavers are absent from the load\nPrivileged access is listed and approved\nStaff can sign in on day one\nLogging meets the agreed control\nAudit can see who approved each role\nHypercare can revoke access the same day\nNo shared user identities\nRecertification finishes before the freeze\nThe security owner signs readiness","assumptions":"Line managers recertify their own staff\nThe identity directory is a source, not a system being replaced\nPrivileged access is a separate list\nLeavers are removed in the source before extract\nCustomer sign-in is owned by the channels delivery\nLogging uses the target platform capability\nEvidence is a record of the approval, not a screenshot folder\nThe hold ends only when a recertification date is set\nNo shared identities are created for go-live\nHypercare revocation uses the same process as business as usual","constraints":"User load cannot start before recertification\nThe freeze date does not move for this workstream alone\nPrivileged access requires two approvers\nPersonal data in access logs follows the retention schedule\nA leaver cannot be loaded\nShared identities are prohibited\nThe hold is visible on the programme overview\nDesign does not restart without the sponsor\nEvidence is kept with the go-live pack\nCustomer credentials are out of this delivery","capabilities":"User profile load\nRole recertification\nPrivileged access list\nLeaver removal\nStaff sign-in\nSecurity logging\nApproval evidence\nSame-day revocation\nAccess enquiry\nReadiness sign-off","systems_in_scope":"Identity and access management directory\nTarget platform access\nLine-manager workflow\nPrivileged access register\nSecurity logging\nStaff directory\nAudit evidence store\nService desk\nHypercare roster\nGo-live pack","environments_in_scope":["development","test"],"business_change_impact":"Line managers recertify who may do what before those users are loaded. Staff sign in through the target access model. Privileged access is separate from day-to-day roles.","overall_rag":"red","schedule_rag":"red","scope_rag":"amber","quality_rag":"amber","cost_rag":"green","headline":"On hold until the access recertification approach is agreed. Line-manager recertification has no date, and that blocks user load.","last_review_date":"2026-10-20","next_review_date":"2026-11-24","key_dependencies":"Recertification date agreed\nLine-manager list confirmed\nPrivileged roles listed\nLeaver extract defined\nLogging requirements signed\nEvidence template agreed\nService desk process for revocation\nSponsor accepts the restart criteria\nChannels delivery owns customer sign-in\nFreeze date reconfirmed","key_risks":"Recertification has no date and the user load misses the freeze\nLeavers are loaded\nA shared identity is created to save time\nPrivileged access is copied unchanged\nLogging is weaker than the agreed control\nLine managers do not complete recertification\nThe hold hides other security work that could continue\nEvidence is not audit-ready\nCustomer sign-in is assumed to be in this delivery\nHypercare cannot revoke on the day","key_issues":"No recertification date is in the plan\nThe workstream is on hold\nPrivileged role list is a draft from the legacy core\nLeaver extract definition is not written\nLogging requirements are not signed\nTwo line-manager areas have no named manager\nThe hold was not reflected on the previous overview\nEvidence template is blank\nService desk revocation process is the legacy one\nRestart criteria are not written down","decisions_needed":"Set a recertification date or keep the hold\nWrite the restart criteria\nName the two missing line managers\nSign the logging requirements\nDefine the leaver extract\nReplace the draft privileged-role list\nConfirm customer sign-in sits with channels\nAdopt an evidence template\nUpdate the service desk revocation process\nShow the hold on the programme overview","delivery_team":"Delivery lead\tNadia Rahman\nBusiness owner\tDaniel Okafor\nExecutive sponsor\tGrace Moyo\nTechnical lead\tNadia Rahman\nAccess analyst\tRavi Pillai\nAudit partner\tOlivia Banda\nService desk lead\tLinda Zhou\nChange lead\tAmina Diallo\nTest lead\tCatherine Mwangi\nRisk partner\tJoy Akinyi","suppliers":"Identity directory support partner\nImplementation partner – access\nSecurity testing partner\nAudit support partner\nTraining partner\nService desk partner\nLogging tooling partner\nPrivileged access review partner\nEvidence tooling partner\nChange partner","approved_budget":1900000,"forecast_to_complete":2100000,"expected_benefits":"Users loaded are users the bank still wants\nLeavers do not keep access\nPrivileged access is visible\nAudit can see the approval\nStaff sign in on day one\nRevocation does not wait for a ticket queue\nA clear hold rather than a hidden slip\nLess argument at go-live about who approved a role\nLogging that matches the agreed control\nA security owner signature on the pack"}$j$),
  ('00000000-0000-4000-a017-000000000008', '00000000-0000-4000-9003-000000000001', 'Environments and release', 'Delivery of the environment path from development through dress rehearsal, production and recovery, and the release calendar that uses it. Owner: Ravi Pillai.', 'in_delivery', $j${"delivery_lead":"Ravi Pillai","business_owner":"Brian Otieno","delivery_type":"platform","delivery_approach":"iterative","current_phase":"build","start_date":"2026-03-16","target_go_live":"2027-04-12","executive_sponsor":"Daniel Okafor","technical_lead":"Ravi Pillai","governance_forum":"Environment and release forum","reporting_cadence":"weekly","escalation_path":"The forum owns environment clashes. A lost dress rehearsal slot, or a production defect caused by a bad refresh, goes to the executive sponsor the same day.","in_scope":"Development environment\nTest environment\nSystem integration environment\nUser acceptance environment\nPre-production\nProduction cutover runbook\nRecovery environment\nRelease calendar\nData refresh request\nEnvironment booking","out_of_scope":"A new data centre build\nEnd-user device replacement\nNetwork redesign\nCloud provider selection\nProduction support model\nMonitoring product selection\nStaff laptop build\nBranch hardware\nPrint room\nArchive hardware","success_criteria":"Every test stage has a booked environment\nDress rehearsal uses a production-like path\nRefresh is requested and logged\nThe release calendar is the only source of release dates\nRecovery is restored and checked before go-live\nNo two mocks share an environment\nProduction runbook is rehearsed\nAccess to production-like data is approved\nBooking clashes are visible\nThe forum signs environment readiness","assumptions":"Existing hosting is reused\nProduction-like data is masked except in dress rehearsal under approval\nOne calendar is enough\nRecovery is a restore test, not a second data centre project\nTeams will book if the booking is easier than asking in a chat\nThe April weekend is reserved now\nRefreshes happen outside test execution\nThe forum can refuse a clash\nRunbooks are steps, not slides\nHypercare uses the production environment","constraints":"The dress rehearsal date is fixed once booked\nMasked data is the default\nProduction access is named people only\nTwo mocks cannot share an environment\nA refresh during execution is refused\nRecovery test evidence is kept\nThe calendar is not a side spreadsheet\nThe April weekend is not used for another release\nBooking is mandatory from SIT onward\nRunbook steps are followed in the rehearsal","capabilities":"Environment booking\nData refresh\nRelease calendar\nMasked data\nDress rehearsal path\nProduction runbook\nRecovery restore\nAccess approval\nClash detection\nReadiness sign-off","systems_in_scope":"Development environment\nTest environment\nSystem integration environment\nUser acceptance environment\nPre-production\nProduction\nRecovery environment\nBooking register\nRelease calendar\nRunbook store","environments_in_scope":["development","test","sit","uat","pre_production","production","dr"],"business_change_impact":"Teams book an environment instead of sharing one informally. Releases follow the calendar. Refreshes are requested, not taken from production by hand.","overall_rag":"green","schedule_rag":"green","scope_rag":"green","quality_rag":"amber","cost_rag":"green","headline":"Development, test and SIT are in use. The dress rehearsal booking is the open item, and production-like data refresh is still manual.","last_review_date":"2026-11-04","next_review_date":"2026-11-18","key_dependencies":"Hosting capacity confirmed\nMasking approach agreed\nApril weekend reserved\nDress rehearsal slot requested\nRefresh process written\nBooking register available\nRecovery backup identifiable\nNamed production access list\nRelease calendar owner named\nRunbook template agreed","key_risks":"Dress rehearsal has no environment\nA refresh uses unmasked production data\nTwo mocks are booked on one environment\nThe April weekend is double-booked\nRecovery backup cannot be restored\nTeams bypass the calendar\nProduction access is wider than the named list\nRunbook steps are skipped in rehearsal\nCapacity runs out before UAT\nA refresh lands during execution","key_issues":"Dress rehearsal environment is not booked\nRefresh is still a manual copy\nMasking rules are drafted and not approved\nThe release calendar is a spreadsheet as well as the register\nRecovery restore has not been attempted\nTwo teams have asked for SIT on the same week\nProduction access list is not written\nRunbook template is agreed\nApril weekend is reserved\nBooking is optional in test and mandatory only from SIT","decisions_needed":"Book the dress rehearsal environment\nApprove the masking rules\nRetire the side spreadsheet\nWrite the production access list\nSchedule the recovery restore\nRefuse the SIT clash\nKeep refresh out of execution windows\nConfirm the April weekend reservation\nMake booking mandatory from SIT\nName the calendar owner","delivery_team":"Delivery lead\tRavi Pillai\nBusiness owner\tBrian Otieno\nExecutive sponsor\tDaniel Okafor\nTechnical lead\tRavi Pillai\nEnvironment analyst\tPriya Naidoo\nRelease manager\tLinda Zhou\nSecurity partner\tNadia Rahman\nTest lead\tCatherine Mwangi\nOperations lead\tAhmed Hassan\nChange lead\tAmina Diallo","suppliers":"Hosting provider\nEnvironment support partner\nMasking tooling partner\nTesting partner\nRecovery test partner\nImplementation partner\nService desk partner\nSecurity testing partner\nTraining partner\nRunbook partner","approved_budget":2200000,"forecast_to_complete":2300000,"expected_benefits":"Tests are not stopped by a clash\nDress rehearsal looks like production\nRefreshes are traceable\nOne calendar for the programme\nA recovery test before it is needed\nLess unmasked data in test\nNamed production access\nA runbook that was actually followed\nCapacity planned rather than discovered\nA signed environment path"}$j$),
  ('00000000-0000-4000-a017-000000000009', '00000000-0000-4000-9003-000000000001', 'Operational readiness and hypercare', 'Delivery of the support model, runbooks, monitoring handover and the hypercare period after go-live. Owner: Linda Zhou.', 'draft', $j${"delivery_lead":"Linda Zhou","business_owner":"Catherine Mwangi","delivery_type":"mixed","delivery_approach":"structured","current_phase":"initiation","start_date":"2026-09-01","target_go_live":"2027-04-12","executive_sponsor":"Grace Moyo","technical_lead":"Ahmed Hassan","governance_forum":"Operational readiness forum","reporting_cadence":"monthly","escalation_path":"The monthly forum is enough while the work is in initiation. From the dress rehearsal onward, a missing runbook or an unstaffed hypercare shift is escalated the same day.","in_scope":"Support model\nRunbooks for the cutover weekend\nHypercare roster\nDaily hypercare bridge\nSeverity scale for hypercare\nMonitoring handover\nKnown-error list\nExit criteria from hypercare\nBusiness-as-usual owner\nStaff communications","out_of_scope":"A new service-desk product\nBranch refurbishment\nA 24-hour contact centre build\nVendor contract renegotiation\nProduction data centre build\nCustomer advertising campaign\nStaff bonus scheme\nLong-term capacity management\nA new major incident process for the whole bank\nDecommission of the legacy cores","success_criteria":"Every cutover step has a runbook someone has walked through\nHypercare shifts are named, including nights\nThe daily bridge has an agenda and a chair\nSeverity scale matches the defect scale\nMonitoring alerts reach the roster\nKnown errors are written down before go-live\nExit criteria are numeric\nA business-as-usual owner is named\nStaff know who to call\nThe sponsor agrees the exit","assumptions":"Hypercare lasts four weeks\nThe existing service desk is the front door\nRunbooks are steps with an expected result\nNight shifts are required for the first week only\nMonitoring is handed over, not rebuilt\nExit is agreed by the sponsor, not assumed at day 28\nBusiness-as-usual owners are the product owners\nCommunications use the existing branch channel\nThe defect scale is reused\nDecommission is a later decision","constraints":"Hypercare cannot be staffed by unnamed roles\nA runbook that has not been walked through does not count\nThe first week has night cover\nExit criteria are set before go-live\nThe bridge is every business day in hypercare\nSeverity 1 has a 30-minute response\nCustomer communications during an incident use the agreed template\nThe service desk is not replaced\nThe roster is published two weeks before dress rehearsal\nBusiness-as-usual ownership starts only after exit","capabilities":"Support model\nCutover runbook\nHypercare roster\nDaily bridge\nSeverity handling\nMonitoring handover\nKnown errors\nExit criteria\nStaff communication\nBusiness-as-usual handover","systems_in_scope":"Service desk\nMonitoring dashboard\nRunbook store\nRoster\nBridge conference\nKnown-error list\nBranch communications\nTarget platform\nIncident log\nGo-live pack","environments_in_scope":["uat","pre_production","production"],"business_change_impact":"Service desk and operations use the target runbooks. Hypercare has a named roster and a daily bridge. After stabilisation the roster stands down and business-as-usual ownership starts.","overall_rag":"amber","schedule_rag":"green","scope_rag":"green","quality_rag":"green","cost_rag":"green","headline":"The readiness workstream is still in initiation. Support model, runbooks and the hypercare roster are named and not yet drafted.","last_review_date":"2026-10-15","next_review_date":"2026-11-20","key_dependencies":"Support model drafted\nRunbook template agreed\nRoster owners identified\nMonitoring owner named\nSeverity scale reused from defects\nBridge chair named\nExit criteria drafted\nBranch communication channel confirmed\nDress rehearsal date known\nSponsor available for the exit decision","key_risks":"Night shifts stay unnamed\nRunbooks are written and never walked through\nHypercare is assumed to end on day 28\nMonitoring alerts go to a mailbox nobody reads\nThe service desk has no script\nSeverity 1 response is slower than 30 minutes\nStaff call the project instead of the desk\nKnown errors are discovered by customers\nThe sponsor is unavailable for exit\nDecommission is started during hypercare","key_issues":"Support model is not drafted\nNo runbook exists yet\nNight shifts are unnamed\nMonitoring owner is not named\nBridge chair is not named\nExit criteria are not drafted\nThe forum meets monthly, which is light for the time left\nService desk script is the legacy script\nKnown-error list does not exist\nBusiness-as-usual owners are assumed, not confirmed","decisions_needed":"Draft the support model before December\nName the bridge chair\nName night-shift leads for week one\nName the monitoring owner\nConfirm product owners as the business-as-usual owners\nDraft exit criteria as numbers\nIncrease the forum to fortnightly from January\nReplace the service desk script\nOpen a known-error list\nKeep decommission out of hypercare","delivery_team":"Delivery lead\tLinda Zhou\nBusiness owner\tCatherine Mwangi\nExecutive sponsor\tGrace Moyo\nTechnical lead\tAhmed Hassan\nService desk lead\tBrian Otieno\nOperations lead\tRavi Pillai\nChange lead\tAmina Diallo\nMonitoring analyst\tPriya Naidoo\nCommunications lead\tNomvula Khumalo\nRisk partner\tNadia Rahman","suppliers":"Service desk partner\nMonitoring provider\nTraining partner\nImplementation partner\nCommunications partner\nHypercare staffing partner\nTesting partner\nDocument management provider\nFacilities for the bridge room\nReport design partner","approved_budget":1500000,"forecast_to_complete":1500000,"expected_benefits":"A weekend someone has already rehearsed\nNamed people on the night shift\nCustomers reach a desk that has a script\nAlerts that reach a person\nA known end to hypercare\nProduct owners who take the service back\nLess dependence on the project team after exit\nStaff who know who to call\nEvidence that the runbook was used\nA calmer first month"}$j$),
  ('00000000-0000-4000-a017-00000000000a', '00000000-0000-4000-9003-000000000001', 'Regulatory reporting', 'Completed delivery of the report-line mapping that lets finance keep the existing reporting tool across the migration. Owner: Olivia Banda.', 'closed', $j${"delivery_lead":"Olivia Banda","business_owner":"Olivia Banda","delivery_type":"enhancement","delivery_approach":"structured","current_phase":"closed","start_date":"2026-02-02","target_go_live":"2026-09-30","executive_sponsor":"Grace Moyo","technical_lead":"Priya Naidoo","governance_forum":"Finance and regulatory forum","reporting_cadence":"monthly","escalation_path":"Closed work. A general-ledger line that changes meaning is raised to the finance forum and reopens only the affected report, not the whole workstream.","in_scope":"Report-line map from the trial balance\nCurrency and company mapping\nFirst mock cross-check\nEvidence pack for finance\nNamed owner per report family\nDifference account treatment\nSign-off by the financial controller\nA reopen rule if a mapped line changes\nHandover to finance business as usual\nShort guide for the mapping","out_of_scope":"A new reporting tool\nPrudential return redesign\nTax engine replacement\nManagement information warehouse\nBoard pack redesign\nCost allocation rebuild\nAccount reconciliation product\nA new chart of accounts\nExternal audit tool\nReal-time finance dashboard","success_criteria":"Every report line used in the last year has a mapped source\nThe mock cross-check agreed\nDifferences go to the agreed difference account\nThe financial controller has signed\nFinance did not change tool\nEvidence is in the go-live pack\nOwners are named\nThe guide is two pages\nReopen rule is written\nThe workstream is closed","assumptions":"The finance system stays\nThe chart of accounts does not change for go-live\nLast year of report lines is the scope\nDifferences use account 14918 as already agreed for the journals\nThe controller is the signer\nA line that changes meaning reopens that report only\nThe guide is maintained by finance after handover\nNo new regulatory return is due before go-live\nCurrency codes are already harmonised enough for this map\nThe pack is evidence, not a new system","constraints":"No new reporting tool\nThe map cannot drop a line used in the last year\nDifferences have one account\nSign-off is the controller, not the project\nThe guide stays short\nPersonal customer data is not in the pack\nReopen does not restart the workstream\nThe September 2026 close stands\nHandover is to named finance owners\nThe April 2027 migration still uses this map","capabilities":"Report-line map\nCurrency mapping\nCompany mapping\nMock cross-check\nDifference account\nEvidence pack\nController sign-off\nReopen rule\nHandover\nShort guide","systems_in_scope":"Finance and general ledger system\nReporting tool\nTrial balance\nMapping sheet\nEvidence store\nDifference account\nTarget take-over accounts\nGo-live pack\nFinance shared area\nController sign-off record","environments_in_scope":["test","uat","production"],"business_change_impact":"Finance keeps the existing reporting tool. Mappers keep the trial balance aligned to the report lines. No finance user moves to a new tool for this programme.","overall_rag":"green","schedule_rag":"green","scope_rag":"green","quality_rag":"green","cost_rag":"green","headline":"The reporting cross-check for the first mock is complete and the workstream is closed. A short reopen is planned only if Mock 3 changes a mapped general-ledger line.","last_review_date":"2026-09-28","next_review_date":"2027-03-31","key_dependencies":"Trial balance owner\nList of report lines from the last year\nDifference account agreed\nController availability\nMapping sheet tool\nEvidence store\nHarmonised currency codes\nCompany codes\nHandover meeting\nReopen rule drafted","key_risks":"A report line was missed\nA mapped line changes meaning before April 2027\nThe difference account is used for something else\nThe controller signature is on the wrong version\nThe guide is not kept\nA new return is announced\nCurrency harmonisation is incomplete for one company\nThe pack holds customer-level data\nHandover owners leave\nThe workstream is treated as open and consumes the team","key_issues":"None open. The missed-line sample was corrected before sign-off\nThe first version of the guide was four pages and was cut\nOne company code was harmonised late and rechecked\nA draft pack page contained a customer sample and was removed\nThe controller signed version 1.1\nHandover meeting was held on 28 September 2026\nReopen rule is in the pack\nTwo owners were confirmed in writing\nThe September close is recorded\nThe team has stood down","decisions_needed":"Close the workstream\nKeep the reopen rule to a single report\nKeep account 14918 as the difference account\nLeave the guide with finance\nDo not select a new reporting tool\nAccept version 1.1 as the signed map\nRemove customer-level rows from the pack\nName two finance owners\nUse the map unchanged in April 2027 unless a line changes meaning\nStand the team down","delivery_team":"Delivery lead\tOlivia Banda\nBusiness owner\tOlivia Banda\nExecutive sponsor\tGrace Moyo\nTechnical lead\tPriya Naidoo\nFinance analyst\tDaniel Okafor\nMapping analyst\tAmina Diallo\nAudit partner\tNadia Rahman\nTest lead\tCatherine Mwangi\nChange lead\tLinda Zhou\nRecords partner\tBrian Otieno","suppliers":"Reporting tool support partner\nImplementation partner – finance mapping\nAudit support partner\nData migration partner\nTraining partner\nDocument management provider\nTesting partner\nService desk partner\nRecords management partner\nChange partner","approved_budget":900000,"forecast_to_complete":860000,"expected_benefits":"Finance keeps a tool it already knows\nReport lines that still tie\nA signed map\nA small guide\nA reopen path that is narrow\nNo extra run cost for a new tool\nEvidence an auditor can read\nOwners who are named\nThe team freed for the financial mock\nA difference account that is already understood"}$j$),
  ('00000000-0000-4000-a018-000000000001', '00000000-0000-4000-9003-000000000003', 'Customer and digital channels', 'Delivery of customer master data and the internet, mobile and branch channels for the Northbridge Bank technology programme. Owner: Amina Diallo. Forum: Channels steering group. Status of the parent delivery is in delivery.', 'in_progress', $j${}$j$),
  ('00000000-0000-4000-a018-000000000002', '00000000-0000-4000-9003-000000000003', 'Payments and transfers', 'Delivery of domestic payments, standing orders and internal transfers onto the target platform. Owner: Ahmed Hassan. Forum: Payments working group. Status of the parent delivery is in delivery.', 'in_progress', $j${}$j$),
  ('00000000-0000-4000-a018-000000000003', '00000000-0000-4000-9003-000000000003', 'Lending, limits and collateral', 'Delivery of loans, limits and collateral, including overdue bills and the expired-limit rule. Owner: Joy Akinyi. Forum: Credit design authority. Status of the parent delivery is in delivery.', 'in_progress', $j${}$j$),
  ('00000000-0000-4000-a018-000000000004', '00000000-0000-4000-9003-000000000003', 'Deposits and accounts', 'Delivery of current accounts, savings and term deposits, including balances and accruals. Owner: Catherine Mwangi. Forum: Deposits product forum. Status of the parent delivery is published.', 'in_progress', $j${}$j$),
  ('00000000-0000-4000-a018-000000000005', '00000000-0000-4000-9003-000000000003', 'Data migration and quality', 'Cross-cutting delivery of extraction, cleansing, transformation, mock runs and reconciliation for the programme. Owner: Priya Naidoo. Forum: Data migration design authority. Status of the parent delivery is in delivery.', 'in_progress', $j${}$j$),
  ('00000000-0000-4000-a018-000000000006', '00000000-0000-4000-9003-000000000003', 'Integration and interfaces', 'Delivery of the interfaces the target platform needs from channels, cards, finance, documents and the user store. Owner: Brian Otieno. Forum: Integration design authority. Status of the parent delivery is in delivery.', 'in_progress', $j${}$j$),
  ('00000000-0000-4000-a018-000000000007', '00000000-0000-4000-9003-000000000003', 'Cybersecurity and access', 'Delivery of user access, recertification and the security controls required before go-live. Currently on hold. Owner: Nadia Rahman. Forum: Security design authority. Status of the parent delivery is on hold.', 'not_started', $j${}$j$),
  ('00000000-0000-4000-a018-000000000008', '00000000-0000-4000-9003-000000000003', 'Environments and release', 'Delivery of the environment path from development through dress rehearsal, production and recovery, and the release calendar that uses it. Owner: Ravi Pillai. Forum: Environment and release forum. Status of the parent delivery is in delivery.', 'in_progress', $j${}$j$),
  ('00000000-0000-4000-a018-000000000009', '00000000-0000-4000-9003-000000000003', 'Operational readiness and hypercare', 'Delivery of the support model, runbooks, monitoring handover and the hypercare period after go-live. Owner: Linda Zhou. Forum: Operational readiness forum. Status of the parent delivery is draft.', 'not_started', $j${}$j$),
  ('00000000-0000-4000-a018-00000000000a', '00000000-0000-4000-9003-000000000003', 'Regulatory reporting', 'Completed delivery of the report-line mapping that lets finance keep the existing reporting tool across the migration. Owner: Olivia Banda. Forum: Finance and regulatory forum. Status of the parent delivery is closed.', 'complete', $j${}$j$),
  ('00000000-0000-4000-a019-000000000001', '00000000-0000-4000-9003-000000000004', 'Business case approved', 'The technology programme business case was approved on 20 January 2026. Sponsor: Grace Moyo.', 'met', $j${}$j$),
  ('00000000-0000-4000-a019-000000000002', '00000000-0000-4000-9003-000000000004', 'Target platform scope signed', 'In-scope populations and the file layout were signed on 16 March 2026.', 'met', $j${}$j$),
  ('00000000-0000-4000-a019-000000000003', '00000000-0000-4000-9003-000000000004', 'Mock 1 static and financial run', 'Mock 1 ran on 12–13 September 2026, overran by 9 hours, and was rerun on 3–4 October 2026.', 'met', $j${}$j$),
  ('00000000-0000-4000-a019-000000000004', '00000000-0000-4000-9003-000000000004', 'Regulatory report-line map signed', 'The financial controller signed mapping version 1.1 on 28 September 2026. The reporting workstream is closed.', 'met', $j${}$j$),
  ('00000000-0000-4000-a019-000000000005', '00000000-0000-4000-9003-000000000004', 'Mock 2 static data', 'Static data mock, including customers and accounts, planned for 14 November 2026. Entry requires the open data-owner forms to be issued.', 'upcoming', $j${}$j$),
  ('00000000-0000-4000-a019-000000000006', '00000000-0000-4000-9003-000000000004', 'Integration SIT entry', 'System integration entry for the twelve in-scope interfaces, including the two slots still to be booked.', 'upcoming', $j${}$j$),
  ('00000000-0000-4000-a019-000000000007', '00000000-0000-4000-9003-000000000004', 'Access recertification complete', 'Line-manager recertification must finish before any user is loaded. The security workstream stays on hold until a date is set.', 'upcoming', $j${}$j$),
  ('00000000-0000-4000-a019-000000000008', '00000000-0000-4000-9003-000000000004', 'Mock 3 financial reconciliation', 'Financial mock. Take-over and suspense accounts are required to finish at zero.', 'upcoming', $j${}$j$),
  ('00000000-0000-4000-a019-000000000009', '00000000-0000-4000-9003-000000000004', 'Dress rehearsal', 'Production-like rehearsal of the freeze, load, reconciliation and rollback. The environment is not yet booked.', 'upcoming', $j${}$j$),
  ('00000000-0000-4000-a019-00000000000a', '00000000-0000-4000-9003-000000000004', 'Go-live and hypercare exit', 'Cutover on the weekend of 10–12 April 2027, then four weeks of hypercare with named night cover in week one.', 'upcoming', $j${}$j$),
  ('00000000-0000-4000-a01a-000000000001', '00000000-0000-4000-9003-000000000002', 'Customer and digital channels roadmap', 'Two-year roadmap for Customer and digital channels on the Northbridge Bank technology programme. Owner: Ravi Pillai.', 'draft', $j${"document_reference":"NRB-RM-01","document_version":"0.9","document_owner":"Amina Diallo","next_review_date":"2026-11-16","roadmap_owner":"Ravi Pillai","horizon":"2_years","roadmap_start":"2026-04-06","purpose":"Delivery of customer master data and the internet, mobile and branch channels for the Northbridge Bank technology programme. Owner: Amina Diallo.","objectives":"Every active customer has one surviving customer number\nAddress completeness at or above 85%\nInternet and mobile users can sign in on day one\nDuplicate customers reduced below 1%\nMandate images linked to the surviving customer\nBranch search returns the customer in under 3 seconds\nNo customer advice sent during the load\nChannel entitlements match the recertified list\nAlternate keys kept for the old customer numbers\nBusiness data owner signs off the customer population","scope":"Retail and SME customer master\nCorporate customer master from the second legacy instance\nInternet banking registration\nMobile banking registration\nBranch teller customer search\nContact centre customer view\nStatement and alert preferences\nMandate and signature images\nCustomer number cross-reference\nChannel entitlement after go-live","out_of_scope":"Card plastic personalisation\nMarketing campaign tool\nLoyalty scheme\nInsurance product origination\nWealth advisory portal\nStaff intranet\nSupplier portal\nRecruitment system\nPayroll\nGeneral ledger close","assumptions":"Both legacy instances are profiled before Mock 2\nThe surviving record is the one with the most complete KYC data\nCustomers accept a new customer number where numbers clash\nBranch staff are trained before the dress rehearsal\nStatement templates are approved by the business\nThe document store can supply images for the load\nIdentity documents already scanned stay valid\nContact centre scripts are rewritten before UAT\nNo new customer products are launched in the freeze week\nThe target customer number is 8 digits","constraints":"Customer numbers must be unique across both legacy instances\nKYC fields are mandatory before a customer can be loaded\nAddress completeness target is 85%\nImages must be linked before the channel is opened\nThe load window is the weekend of 10–12 April 2027\nNo marketing mail is sent from the load\nPersonal data stays in the bank residency region\nBranch capture stops at the freeze\nOld numbers are kept for seven years\nThe channel cutover is the same weekend as the financial load","vision":"Northbridge Bank runs customer and digital channels on the target platform after the April 2027 weekend, with the legacy cores read-only.","business_drivers":"One customer number for service and channels\nFewer duplicate records for staff to reconcile\nCustomers keep digital access on day one\nFaster branch and contact centre search\nCleaner KYC for ongoing due diligence\nLess manual repair after go-live\nA single place to turn alerts on or off\nOld numbers remain searchable\nLower cost of maintaining two customer masters\nA signed customer population for the financial load","principles":"One owner for the population\nCleanse in the source\nKeep an alternate key for the legacy reference\nNo new tool unless the existing one cannot do the job\nRehearse before the weekend\nSign-off is by the business owner\nPersonal data stays in the residency region\nA red item is visible on the overview\nEvidence is kept for the retention period\nVendor-neutral names in every artefact","current_technologies":"Legacy core – retail and SME instance\nLegacy core – corporate instance\nInternet banking\nMobile banking\nBranch teller\nContact centre desktop\nDocument imaging system\nCustomer due diligence repository\nDigital banking user store\nTarget customer master","constraints_and_issues":"Address completeness measured at 82% after Mock 1\n23,400 customers exist in both legacy instances\n4,150 customers have more than one number in a single instance\nImage storage location is not decided\nKYC extract access is requested, not yet granted\nContact centre scripts are still the legacy wording\nTwo statement templates are awaiting brand approval\nBranch champions are not named in 12 branches\nMobile registration test users were not refreshed after Mock 1\nCustomer advice suppression was missed in an early SIT load","initiatives":"Single customer view – build – Every active customer has one surviving customer number\nCustomer deduplication – build – Address completeness at or above 85%\nInternet banking sign-in – build – Internet and mobile users can sign in on day one\nMobile banking sign-in – build – Duplicate customers reduced below 1%\nBranch customer search – build – Mandate images linked to the surviving customer\nContact centre desktop – build – Branch search returns the customer in under 3 seconds\nStatement preferences – build – No customer advice sent during the load\nAlert preferences – build – Channel entitlements match the recertified list\nMandate viewing – build – Alternate keys kept for the old customer numbers\nCustomer number cross-reference – build – Business data owner signs off the customer population","milestones":"2026-01-20 – Business case approved\n2026-03-16 – Target platform scope signed\n2026-10-04 – Mock 1 static and financial run\n2026-09-28 – Regulatory report-line map signed\n2026-11-14 – Mock 2 static data\n2026-12-07 – Integration SIT entry\n2027-01-29 – Access recertification complete\n2027-01-16 – Mock 3 financial reconciliation\n2027-03-06 – Dress rehearsal\n2027-05-10 – Go-live and hypercare exit","dependencies":"Customer deduplication rules signed off\nKYC repository extract granted\nDocument image storage decision\nTarget customer products configured\n8-digit numbering agreed\nStatement templates approved\nContact centre trained\nBranch freeze communications sent\nMock 2 static load passed\nChannel entitlements recertified","estimated_investment":4800000,"funding_sources":"Programme budget\nBusiness area budget\nShared technology fund\nTraining budget\nHypercare contingency\nEnvironment capacity\nMigration partner statement of work\nTesting partner statement of work\nNo new capital request in this slice\nBenefits tracked by finance","review_cadence":"monthly","kpis":"Every active customer has one surviving customer number\nAddress completeness at or above 85%\nInternet and mobile users can sign in on day one\nDuplicate customers reduced below 1%\nMandate images linked to the surviving customer\nBranch search returns the customer in under 3 seconds\nNo customer advice sent during the load\nChannel entitlements match the recertified list\nAlternate keys kept for the old customer numbers\nBusiness data owner signs off the customer population","risks_mitigations":"Address completeness stays under 85% – Confirm the survivor rule for duplicate customers\nDuplicate customers are merged onto the wrong survivor – Decide image storage: file store or database\nImage volume slips the static window – Approve the two outstanding statement templates\nCustomers cannot sign in on day one – Name a champion in every branch\nOld customer numbers are dropped – Confirm KYC extract access by 30 November 2026\nBranch staff keep using the legacy screens – Agree the customer communication for changed numbers\nStatement templates are late – Choose the contact centre go-live script\nKYC extract access is still only requested – Confirm advice suppression is on the pre-migration checklist\nPersonal data leaves the agreed region – Accept the 8-digit customer number standard\nChannel and financial cutovers fall on different weekends – Confirm channel cutover is the same weekend as the financial load","roles_and_responsibilities":"Delivery lead – Amina Diallo\nBusiness owner – Nomvula Khumalo\nExecutive sponsor – Grace Moyo\nTechnical lead – Ravi Pillai\nData analyst – Priya Naidoo\nChannel analyst – Brian Otieno\nTest lead – Catherine Mwangi\nTraining lead – Linda Zhou\nSecurity partner – Nadia Rahman\nChange lead – Daniel Okafor","glossary":"Alternate key\tThe legacy reference kept so old numbers remain searchable\nFreeze\tThe point after which the legacy core takes no new business\nTake-over account\tThe account that receives migrated balances and must return to zero\nMock\tA full practice load used to prove the migration\nDress rehearsal\tThe final practice on a production-like path\nHypercare\tThe staffed support period after go-live\nSurvivor\tThe customer record kept when duplicates are merged\nPopulation\tThe set of records a data owner signs\nControl total\tThe figure the load must match, usually from the trial balance\nReadiness\tThe signed statement that a slice can enter the next stage","appendices":"Appendix 1\tRetail and SME customer master\nAppendix 2\tCorporate customer master from the second legacy instance\nAppendix 3\tInternet banking registration\nAppendix 4\tMobile banking registration\nAppendix 5\tBranch teller customer search\nAppendix 6\tContact centre customer view\nAppendix 7\tStatement and alert preferences\nAppendix 8\tMandate and signature images\nAppendix 9\tCustomer number cross-reference\nAppendix 10\tChannel entitlement after go-live","version_history":"0.9\t2026-11-02\tAmina Diallo\tSample baseline for the Northbridge programme","related_documents":"Technology delivery overview for this slice\nData migration strategy\nInterface register\nOperational readiness notes\nGo-live pack"}$j$),
  ('00000000-0000-4000-a01a-000000000002', '00000000-0000-4000-9003-000000000002', 'Payments and transfers roadmap', 'Two-year roadmap for Payments and transfers on the Northbridge Bank technology programme. Owner: Brian Otieno.', 'draft', $j${"document_reference":"NRB-RM-02","document_version":"0.9","document_owner":"Ahmed Hassan","next_review_date":"2026-11-18","roadmap_owner":"Brian Otieno","horizon":"2_years","roadmap_start":"2026-05-04","purpose":"Delivery of domestic payments, standing orders and internal transfers onto the target platform. Owner: Ahmed Hassan.","objectives":"Every active standing order is recreated before go-live\nSettlement totals agree to the cent\nReturned payments land on the repair queue\nChannel limits match the signed matrix\nNo duplicate payment on the cutover weekend\nCut-off calendar loaded for the next 18 months\nOperations can repair a payment without the legacy core\nCustomer payment references are preserved\nScheme window is met on the first business day\nBusiness owner signs off the payment population","scope":"Domestic credit transfers\nInternal account transfers\nStanding orders\nFuture-dated payments\nPayment limits by channel\nSettlement timetable\nUnpaid and returned payments\nPayment repair queue\nScheme cut-off calendar\nPayment reference cross-reference","out_of_scope":"Card authorisation\nATM cash\nCheque clearing replacement\nCross-border correspondent banking rebuild\nCash-in-transit\nPoint of sale acquiring\nMerchant settlement\nCrypto assets\nOpen-banking directory membership\nPayroll file payments","assumptions":"The scheme timetable does not change before go-live\nStanding orders are recreated, not replayed from history\nBoth legacy instances use the same value-date rule\nPayment limits are signed by the business before UAT\nThe repair queue is staffed for hypercare\nTest scheme membership stays available through dress rehearsal\nFuture-dated payments inside the freeze are cancelled and re-entered\nCustomer accounts exist before payments are loaded\nNo new payment type is added after design approval\nThe first business day is a normal scheme day","constraints":"Scheme cut-off cannot move\nSettlement must balance on the night\nStanding orders with an end date in the past are excluded\nDual control stays on the repair queue\nPayment files are not accepted during the freeze\nLimits cannot exceed the signed matrix\nThe load finishes before the first scheme window\nPersonal payment references are not printed on operations reports\nReturned items are visible the same morning\nHypercare cover runs for four weeks","vision":"Northbridge Bank runs payments and transfers on the target platform after the April 2027 weekend, with the legacy cores read-only.","business_drivers":"One payment engine instead of two cores\nStanding orders survive the cutover\nFaster repair of returned payments\nSettlement that operations can explain\nClearer channel limits\nLess manual standing-order repair\nA calendar operations can plan to\nCustomer references preserved on enquiries\nLower run cost after decommission\nA signed payment population for go-live","principles":"One owner for the population\nCleanse in the source\nKeep an alternate key for the legacy reference\nNo new tool unless the existing one cannot do the job\nRehearse before the weekend\nSign-off is by the business owner\nPersonal data stays in the residency region\nA red item is visible on the overview\nEvidence is kept for the retention period\nVendor-neutral names in every artefact","current_technologies":"Legacy core – both instances\nTarget payments engine\nScheme gateway\nChannel payment screens\nStanding order store\nRepair workflow\nSettlement reports\nLimits service\nCustomer notifications\nOperations dashboard","constraints_and_issues":"1,180 standing orders exist in both instances\nScheme certificate renewal is with the gateway team\nTwo limit bands are still in draft\nRepair training is booked but not delivered\nNotification suppression failed once in SIT\nCut-off calendar stops at December 2027 and must be extended\nUAT funding for payment accounts is not yet approved\nA test file used production account numbers\nReturned-item report layout is not signed\nHypercare roster has two unnamed night shifts","initiatives":"Domestic credit transfer – test – Every active standing order is recreated before go-live\nInternal transfer – test – Settlement totals agree to the cent\nStanding order booking – test – Returned payments land on the repair queue\nFuture-dated payment – test – Channel limits match the signed matrix\nPayment limits – test – No duplicate payment on the cutover weekend\nSettlement – test – Cut-off calendar loaded for the next 18 months\nReturns and unpaids – test – Operations can repair a payment without the legacy core\nRepair queue – test – Customer payment references are preserved\nCut-off calendar – test – Scheme window is met on the first business day\nPayment enquiry – test – Business owner signs off the payment population","milestones":"2026-01-20 – Business case approved\n2026-03-16 – Target platform scope signed\n2026-10-04 – Mock 1 static and financial run\n2026-09-28 – Regulatory report-line map signed\n2026-11-14 – Mock 2 static data\n2026-12-07 – Integration SIT entry\n2027-01-29 – Access recertification complete\n2027-01-16 – Mock 3 financial reconciliation\n2027-03-06 – Dress rehearsal\n2027-05-10 – Go-live and hypercare exit","dependencies":"Customer and account numbers mapped\nScheme gateway certificate renewed\nLimit matrix signed\nSettlement accounts configured\nCut-off calendar agreed with operations\nRepair roles assigned\nUAT payment accounts funded\nNotification templates approved\nMock 2 payment file compared\nHypercare roster published","estimated_investment":3100000,"funding_sources":"Programme budget\nBusiness area budget\nShared technology fund\nTraining budget\nHypercare contingency\nEnvironment capacity\nMigration partner statement of work\nTesting partner statement of work\nNo new capital request in this slice\nBenefits tracked by finance","review_cadence":"monthly","kpis":"Every active standing order is recreated before go-live\nSettlement totals agree to the cent\nReturned payments land on the repair queue\nChannel limits match the signed matrix\nNo duplicate payment on the cutover weekend\nCut-off calendar loaded for the next 18 months\nOperations can repair a payment without the legacy core\nCustomer payment references are preserved\nScheme window is met on the first business day\nBusiness owner signs off the payment population","risks_mitigations":"Standing orders are duplicated across the two instances – Confirm standing orders are recreated rather than replayed\nScheme certificate expires before dress rehearsal – Extend the cut-off calendar through October 2028\nSettlement does not balance on the night – Approve UAT funding for payment accounts\nRepair queue is understaffed on day one – Name the two night-shift hypercare leads\nFuture-dated payments are lost in the freeze – Sign the remaining limit bands\nChannel limits are looser than the signed matrix – Confirm notification suppression on the checklist\nA scheme change lands inside the freeze – Accept the returned-item report layout\nCustomer notifications fire during the load – Choose the survivor standing order where both instances hold one\nValue dates shift by a day – Confirm the first business day scheme window\nThe first business day is a scheme holiday – Agree dual control on the repair queue","roles_and_responsibilities":"Delivery lead – Ahmed Hassan\nBusiness owner – Catherine Mwangi\nExecutive sponsor – Daniel Okafor\nTechnical lead – Brian Otieno\nSettlement analyst – Olivia Banda\nTest lead – Priya Naidoo\nOperations lead – Linda Zhou\nSecurity partner – Nadia Rahman\nChange lead – Amina Diallo\nChannel analyst – Ravi Pillai","glossary":"Alternate key\tThe legacy reference kept so old numbers remain searchable\nFreeze\tThe point after which the legacy core takes no new business\nTake-over account\tThe account that receives migrated balances and must return to zero\nMock\tA full practice load used to prove the migration\nDress rehearsal\tThe final practice on a production-like path\nHypercare\tThe staffed support period after go-live\nSurvivor\tThe customer record kept when duplicates are merged\nPopulation\tThe set of records a data owner signs\nControl total\tThe figure the load must match, usually from the trial balance\nReadiness\tThe signed statement that a slice can enter the next stage","appendices":"Appendix 1\tDomestic credit transfers\nAppendix 2\tInternal account transfers\nAppendix 3\tStanding orders\nAppendix 4\tFuture-dated payments\nAppendix 5\tPayment limits by channel\nAppendix 6\tSettlement timetable\nAppendix 7\tUnpaid and returned payments\nAppendix 8\tPayment repair queue\nAppendix 9\tScheme cut-off calendar\nAppendix 10\tPayment reference cross-reference","version_history":"0.9\t2026-11-04\tAhmed Hassan\tSample baseline for the Northbridge programme","related_documents":"Technology delivery overview for this slice\nData migration strategy\nInterface register\nOperational readiness notes\nGo-live pack"}$j$),
  ('00000000-0000-4000-a01a-000000000003', '00000000-0000-4000-9003-000000000002', 'Lending, limits and collateral roadmap', 'Two-year roadmap for Lending, limits and collateral on the Northbridge Bank technology programme. Owner: Priya Naidoo.', 'draft', $j${"document_reference":"NRB-RM-03","document_version":"0.9","document_owner":"Joy Akinyi","next_review_date":"2026-11-11","roadmap_owner":"Priya Naidoo","horizon":"2_years","roadmap_start":"2026-05-18","purpose":"Delivery of loans, limits and collateral, including overdue bills and the expired-limit rule. Owner: Joy Akinyi.","objectives":"Every live loan has an arrangement, a balance and a schedule\nAgeing continues from the legacy past-due date\nExpired limits follow the signed rule\nCollateral is linked before the loan is loaded\nOne repayment account per customer per currency\nTake-over accounts return to zero\nCredit can enquire without the legacy core\nAccrual is not double-counted\nMapping sheet is approved before Mock 2\nCredit signs the loan population","scope":"Retail loan arrangements\nCorporate loan arrangements\nOverdue and due bills\nAccrued interest on loans\nLimit records\nExpired limits still linked to a contract\nCollateral rights\nCollateral items\nRepayment account selection\nCredit enquiry","out_of_scope":"New scorecard build\nDebt collection agency files\nSecuritisation\nSyndicated loan agency\nTrade finance instruments\nTreasury dealing\nCard instalment plans\nStaff loans policy rewrite\nProvisioning model rebuild\nRegulatory capital calculator","assumptions":"Schedules are regenerated from the migrated frequency\nThe expired-limit rule is expiry plus one day, with the original date kept\nOne liquidation account is allowed per customer per currency\nCollateral rights load before collateral items\nPast-due date becomes the bill date\nNo new loan product is launched after design approval\nCredit officers are trained before UAT\nTake-over accounts are configured by finance\nBoth instances use the same accrual convention\nLimits keep an alternate key","constraints":"A loan cannot load before its customer and account\nCollateral cannot load before its right\nAgeing must not reset to zero\nExpired limits cannot be dropped while a contract is live\nTake-over accounts must be zero after reconciliation\nDual control remains on limit changes\nThe design authority meets every two weeks\nPersonal income data is not copied to operations reports\nMock 2 cannot start with the mapping sheet in draft\nThe April 2027 weekend is fixed","vision":"Northbridge Bank runs lending, limits and collateral on the target platform after the April 2027 weekend, with the legacy cores read-only.","business_drivers":"One lending record instead of two cores\nAgeing that collections can trust\nLimits that still secure live contracts\nCollateral linked to the right customer\nLess manual schedule repair\nA take-over that finance can explain\nCredit officers leave the legacy screens\nClearer repayment instructions\nA signed loan population\nLower run cost after decommission","principles":"One owner for the population\nCleanse in the source\nKeep an alternate key for the legacy reference\nNo new tool unless the existing one cannot do the job\nRehearse before the weekend\nSign-off is by the business owner\nPersonal data stays in the residency region\nA red item is visible on the overview\nEvidence is kept for the retention period\nVendor-neutral names in every artefact","current_technologies":"Legacy core – both instances\nTarget lending module\nLimits service\nCollateral register\nCredit workflow\nTake-over accounts\nDocument imaging system\nCustomer master\nRepayment account service\nCredit reporting","constraints_and_issues":"Schedule design is two weeks behind the plan\n2,180 expired limits are not yet reviewed\n8,900 loans still have more than one repayment account\nCollateral mapping is approved but the load order is not rehearsed\nTake-over account for loans is not opened\nAccrual treatment is with finance\nCredit training dates clash with branch training\nMapping sheet status is still draft\nOne limit band has no owner\nMock 2 entry criteria do not mention the mapping sheet","initiatives":"Loan arrangement – design – Every live loan has an arrangement, a balance and a schedule\nBalance and accrual capture – design – Ageing continues from the legacy past-due date\nBill and ageing – design – Expired limits follow the signed rule\nLimit maintenance – design – Collateral is linked before the loan is loaded\nExpired-limit rule – design – One repayment account per customer per currency\nCollateral right – design – Take-over accounts return to zero\nCollateral item – design – Credit can enquire without the legacy core\nRepayment account – design – Accrual is not double-counted\nCredit enquiry – design – Mapping sheet is approved before Mock 2\nTake-over reconciliation – design – Credit signs the loan population","milestones":"2026-01-20 – Business case approved\n2026-03-16 – Target platform scope signed\n2026-10-04 – Mock 1 static and financial run\n2026-09-28 – Regulatory report-line map signed\n2026-11-14 – Mock 2 static data\n2026-12-07 – Integration SIT entry\n2027-01-29 – Access recertification complete\n2027-01-16 – Mock 3 financial reconciliation\n2027-03-06 – Dress rehearsal\n2027-05-10 – Go-live and hypercare exit","dependencies":"Customer numbers mapped\nExpired-limit rule signed by credit\nRepayment account rule signed\nCollateral identifier format agreed\nTake-over accounts opened\nMapping sheet out of draft\nCredit training plan approved\nMock 2 dates held\nFinance agrees the accrual treatment\nDocument links for collateral schedules","estimated_investment":5400000,"funding_sources":"Programme budget\nBusiness area budget\nShared technology fund\nTraining budget\nHypercare contingency\nEnvironment capacity\nMigration partner statement of work\nTesting partner statement of work\nNo new capital request in this slice\nBenefits tracked by finance","review_cadence":"quarterly","kpis":"Every live loan has an arrangement, a balance and a schedule\nAgeing continues from the legacy past-due date\nExpired limits follow the signed rule\nCollateral is linked before the loan is loaded\nOne repayment account per customer per currency\nTake-over accounts return to zero\nCredit can enquire without the legacy core\nAccrual is not double-counted\nMapping sheet is approved before Mock 2\nCredit signs the loan population","risks_mitigations":"Schedule design slips Mock 2 – Sign the expired-limit rule\nExpired limits are dropped and a contract is left unsecured – Open the loan take-over account\nAgeing resets and collections mis-prioritise – Confirm one repayment account per customer per currency\nTake-over accounts do not return to zero – Name an owner for the remaining limit band\nCollateral loads before its right and is rejected – Move credit training ahead of UAT\nTwo repayment accounts remain and the load fails – Add the mapping sheet to the Mock 2 entry criteria\nAccrual is counted twice – Agree accrual treatment with finance\nCredit training is after UAT starts – Rehearse collateral load order\nThe mapping sheet stays in draft – Accept regenerated schedules\nA product rule changes a customer balance without finance agreement – Confirm ageing uses the legacy past-due date","roles_and_responsibilities":"Delivery lead – Joy Akinyi\nBusiness owner – Daniel Okafor\nExecutive sponsor – Grace Moyo\nTechnical lead – Priya Naidoo\nCredit analyst – Ahmed Hassan\nCollateral analyst – Linda Zhou\nFinance partner – Olivia Banda\nTest lead – Catherine Mwangi\nData analyst – Amina Diallo\nChange lead – Brian Otieno","glossary":"Alternate key\tThe legacy reference kept so old numbers remain searchable\nFreeze\tThe point after which the legacy core takes no new business\nTake-over account\tThe account that receives migrated balances and must return to zero\nMock\tA full practice load used to prove the migration\nDress rehearsal\tThe final practice on a production-like path\nHypercare\tThe staffed support period after go-live\nSurvivor\tThe customer record kept when duplicates are merged\nPopulation\tThe set of records a data owner signs\nControl total\tThe figure the load must match, usually from the trial balance\nReadiness\tThe signed statement that a slice can enter the next stage","appendices":"Appendix 1\tRetail loan arrangements\nAppendix 2\tCorporate loan arrangements\nAppendix 3\tOverdue and due bills\nAppendix 4\tAccrued interest on loans\nAppendix 5\tLimit records\nAppendix 6\tExpired limits still linked to a contract\nAppendix 7\tCollateral rights\nAppendix 8\tCollateral items\nAppendix 9\tRepayment account selection\nAppendix 10\tCredit enquiry","version_history":"0.9\t2026-10-28\tJoy Akinyi\tSample baseline for the Northbridge programme","related_documents":"Technology delivery overview for this slice\nData migration strategy\nInterface register\nOperational readiness notes\nGo-live pack"}$j$),
  ('00000000-0000-4000-a01a-000000000004', '00000000-0000-4000-9003-000000000002', 'Deposits and accounts roadmap', 'Two-year roadmap for Deposits and accounts on the Northbridge Bank technology programme. Owner: Brian Otieno.', 'draft', $j${"document_reference":"NRB-RM-04","document_version":"0.9","document_owner":"Catherine Mwangi","next_review_date":"2026-11-17","roadmap_owner":"Brian Otieno","horizon":"2_years","roadmap_start":"2026-04-20","purpose":"Delivery of current accounts, savings and term deposits, including balances and accruals. Owner: Catherine Mwangi.","objectives":"Every open account has a product, a balance and an owner\nInstance 2 account numbers are kept as alternate keys\nDormant accounts over five years are closed or transferred\nMatured deposits no longer carry a balance at the freeze\nRestrictions match the legacy narrative\nStatement frequency is remapped\nBalances agree by product and currency\nAccrual value date is the migration date\nCustomers can enquire on day one\nProduct owners sign the population","scope":"Current accounts\nSavings accounts\nTerm deposits\nDeposit balances and accruals\nDormant accounts over five years\nMatured deposits that still hold a balance\nAccount restrictions\nStatement frequency\nAlternate account keys for the second instance\nAccount enquiry","out_of_scope":"Safe custody\nNew savings product launch\nPrize-linked savings\nChildren account campaign\nBrokerage cash accounts\nTrust accounting\nMulti-currency wallet\nInterest rate change programme\nBranch cash holdings\nGeneral ledger rebuild","assumptions":"Three legacy current-account products become one target product\nInstance 2 numbers become 10 digits with a check digit\nDormant means no customer-initiated transaction for five years\nUnclaimed balances move under the existing regulation\nMatured deposits are paid out or rolled, not migrated as running\nStatement frequency is remapped only where it is not the default\nRestrictions carry their narrative\nFinance owns the balance control total\nNo account is closed in the week before go-live\nThe target allows the signed product set only","constraints":"No account closures in the week before go-live\nA zero-balance account marked for closure is excluded\nAlternate keys are mandatory for instance 2\nAccrual value date cannot be the original accrual date\nProduct mapping cannot change after Mock 2 without a new approval\nDormant processing finishes in November 2026\nControl totals come from the trial balance\nPersonal balances are not listed on the operations dashboard\nThe freeze starts at the final close of business\nEnquiry must work without the legacy core","vision":"Northbridge Bank runs deposits and accounts on the target platform after the April 2027 weekend, with the legacy cores read-only.","business_drivers":"One account record for the customer\nDeposits that are actually running on day one\nDormant balances treated under the existing rule\nRestrictions staff can read\nStatements on the frequency the customer expects\nOld account numbers still searchable\nFinance can tie balances to the trial balance\nLess repair of matured deposits after go-live\nBranches stop using two cores\nA signed account population","principles":"One owner for the population\nCleanse in the source\nKeep an alternate key for the legacy reference\nNo new tool unless the existing one cannot do the job\nRehearse before the weekend\nSign-off is by the business owner\nPersonal data stays in the residency region\nA red item is visible on the overview\nEvidence is kept for the retention period\nVendor-neutral names in every artefact","current_technologies":"Legacy core – both instances\nTarget accounts module\nTarget deposits module\nRestrictions service\nStatement engine\nTake-over accounts\nCustomer master\nFinance trial balance\nBranch screens\nEnquiry service","constraints_and_issues":"1,320 matured deposits still carry a balance\n18,700 dormant accounts are identified and not yet processed\nRestriction narratives are mapped but not sample-checked\nStatement frequency remapping has not started\nTake-over account for deposits is open\nBranch freeze notice is in draft\nTwo product codes remain mapped to a retired target product\nSample of alternate keys passed\nEnquiry test was not run at branch volume\nNovember dormant workshop is not on the branch calendar","initiatives":"Current account – test – Every open account has a product, a balance and an owner\nSavings account – test – Instance 2 account numbers are kept as alternate keys\nTerm deposit – test – Dormant accounts over five years are closed or transferred\nBalance and accrual capture – test – Matured deposits no longer carry a balance at the freeze\nRestriction – test – Restrictions match the legacy narrative\nStatement frequency – test – Statement frequency is remapped\nAlternate account key – test – Balances agree by product and currency\nDormant processing – test – Accrual value date is the migration date\nAccount enquiry – test – Customers can enquire on day one\nBalance reconciliation – test – Product owners sign the population","milestones":"2026-01-20 – Business case approved\n2026-03-16 – Target platform scope signed\n2026-10-04 – Mock 1 static and financial run\n2026-09-28 – Regulatory report-line map signed\n2026-11-14 – Mock 2 static data\n2026-12-07 – Integration SIT entry\n2027-01-29 – Access recertification complete\n2027-01-16 – Mock 3 financial reconciliation\n2027-03-06 – Dress rehearsal\n2027-05-10 – Go-live and hypercare exit","dependencies":"Product mapping approved\n10-digit account standard agreed\nDormant population identified\nMatured-deposit population identified\nTake-over accounts opened\nStatement engine configured\nRestriction code map signed\nFinance control-total owner named\nMock 2 account file compared\nBranch freeze notice drafted","estimated_investment":2600000,"funding_sources":"Programme budget\nBusiness area budget\nShared technology fund\nTraining budget\nHypercare contingency\nEnvironment capacity\nMigration partner statement of work\nTesting partner statement of work\nNo new capital request in this slice\nBenefits tracked by finance","review_cadence":"quarterly","kpis":"Every open account has a product, a balance and an owner\nInstance 2 account numbers are kept as alternate keys\nDormant accounts over five years are closed or transferred\nMatured deposits no longer carry a balance at the freeze\nRestrictions match the legacy narrative\nStatement frequency is remapped\nBalances agree by product and currency\nAccrual value date is the migration date\nCustomers can enquire on day one\nProduct owners sign the population","risks_mitigations":"Matured deposits are still open at the freeze – Confirm matured deposits are paid out or rolled, not migrated as running\nDormant processing slips past November – Put the dormant workshop on the November branch calendar\nAccount numbers clash across the two instances – Retire the two product codes that point at a retired product\nA restriction narrative is dropped – Start statement-frequency remapping\nStatement frequency defaults incorrectly – Sample-check restriction narratives\nTake-over does not return to zero – Approve the branch freeze notice\nStaff close accounts in the freeze week – Keep the rule of no closures in the week before go-live\nProduct mapping is reopened after Mock 2 – Confirm finance owns the balance control total\nAccrual is double-counted – Accept 10-digit numbers with a check digit\nEnquiry is slow on the first morning – Schedule an enquiry test at branch volume","roles_and_responsibilities":"Delivery lead – Catherine Mwangi\nBusiness owner – Nomvula Khumalo\nExecutive sponsor – Olivia Banda\nTechnical lead – Brian Otieno\nProduct analyst – Amina Diallo\nFinance partner – Daniel Okafor\nTest lead – Priya Naidoo\nOperations lead – Linda Zhou\nChange lead – Ahmed Hassan\nData analyst – Joy Akinyi","glossary":"Alternate key\tThe legacy reference kept so old numbers remain searchable\nFreeze\tThe point after which the legacy core takes no new business\nTake-over account\tThe account that receives migrated balances and must return to zero\nMock\tA full practice load used to prove the migration\nDress rehearsal\tThe final practice on a production-like path\nHypercare\tThe staffed support period after go-live\nSurvivor\tThe customer record kept when duplicates are merged\nPopulation\tThe set of records a data owner signs\nControl total\tThe figure the load must match, usually from the trial balance\nReadiness\tThe signed statement that a slice can enter the next stage","appendices":"Appendix 1\tCurrent accounts\nAppendix 2\tSavings accounts\nAppendix 3\tTerm deposits\nAppendix 4\tDeposit balances and accruals\nAppendix 5\tDormant accounts over five years\nAppendix 6\tMatured deposits that still hold a balance\nAppendix 7\tAccount restrictions\nAppendix 8\tStatement frequency\nAppendix 9\tAlternate account keys for the second instance\nAppendix 10\tAccount enquiry","version_history":"0.9\t2026-11-03\tCatherine Mwangi\tSample baseline for the Northbridge programme","related_documents":"Technology delivery overview for this slice\nData migration strategy\nInterface register\nOperational readiness notes\nGo-live pack"}$j$),
  ('00000000-0000-4000-a01a-000000000005', '00000000-0000-4000-9003-000000000002', 'Data migration and quality roadmap', 'Two-year roadmap for Data migration and quality on the Northbridge Bank technology programme. Owner: Brian Otieno.', 'draft', $j${"document_reference":"NRB-RM-05","document_version":"0.9","document_owner":"Priya Naidoo","next_review_date":"2026-11-13","roadmap_owner":"Brian Otieno","horizon":"2_years","roadmap_start":"2026-03-02","purpose":"Cross-cutting delivery of extraction, cleansing, transformation, mock runs and reconciliation for the programme. Owner: Priya Naidoo.","objectives":"Mock 2 static data loads inside the window\nMock 3 financial data reconciles\nDress rehearsal finishes with no severity-1 defect open\nTake-over and suspense accounts are zero\nEach population has a named data owner\nControl totals tie to the trial balance\nExtracts follow the agreed file layout\nCleansing backlog is clear before the freeze\nRollback is rehearsed\nThe go/no-go pack is complete","scope":"Source profiling\nExtraction from both legacy instances\nCleansing at source\nTransformation rules\nMock runs\nDress rehearsal\nReconciliation by product and currency\nTake-over and suspense accounts\nControl totals\nBusiness sign-off of each population","out_of_scope":"Building the target platform\nCard scheme certification\nGeneral ledger replacement\nStaff identity directory rebuild\nA new data warehouse\nHistorical transaction archive design\nCustomer communication creative\nBranch refurbishment\nVendor contract negotiation\nRegulatory return redesign","assumptions":"Three mock runs and one dress rehearsal are enough\nCleansing is done in the source, not in the load\nThe file layout is plain text, one record per line\nDates travel as YYYYMMDD\nControl totals come from the final close of business\nData owners can halt a load\nThe legacy cores can be frozen\nTake-over accounts are opened before Mock 2\nNo new source is added after Mock 2\nHistory beyond the agreed scope is archived, not loaded","constraints":"The April 2027 weekend is fixed\nPersonal data stays in the residency region\nA population cannot load before its predecessor\nSeverity-1 defects block the next mock\nTake-over accounts must finish at zero\nExtracts are taken after close of business\nThe freeze allows no new business\nSign-off is by the data owner, not the project alone\nFile layout cannot change after Mock 2 without approval\nEvidence is kept for the retention period","vision":"Northbridge Bank runs data migration and quality on the target platform after the April 2027 weekend, with the legacy cores read-only.","business_drivers":"A load the bank can explain to audit\nControl totals that match the trial balance\nLess manual repair after go-live\nData owners who have signed their population\nA rehearsed rollback\nOne file layout for every source\nEvidence for the retention period\nFewer duplicate customers reaching the target\nA freeze the branches understand\nA go/no-go pack that is complete","principles":"One owner for the population\nCleanse in the source\nKeep an alternate key for the legacy reference\nNo new tool unless the existing one cannot do the job\nRehearse before the weekend\nSign-off is by the business owner\nPersonal data stays in the residency region\nA red item is visible on the overview\nEvidence is kept for the retention period\nVendor-neutral names in every artefact","current_technologies":"Legacy core – both instances\nDocument imaging system\nFinance and general ledger system\nCustomer due diligence repository\nMigration tool\nTarget platform\nTake-over accounts\nReconciliation workbook\nDefect register\nSign-off store","constraints_and_issues":"Mock 1 take-over accounts were not at zero\nMock 1 overran by 9 hours and was rerun on 3–4 October 2026\nKYC extract access is still requested\nImage storage decision is open\nTwo data-owner sign-off forms are not issued\nA shared workbook held a customer sample longer than agreed\nFile layout examples are missing the multi-value case\nDress rehearsal environment is not booked\nRollback steps are an outline\nThe defect scale is agreed but not on the mock entry checklist","initiatives":"Profiling – test – Mock 2 static data loads inside the window\nExtraction – test – Mock 3 financial data reconciles\nCleansing tracking – test – Dress rehearsal finishes with no severity-1 defect open\nTransformation – test – Take-over and suspense accounts are zero\nMock run – test – Each population has a named data owner\nReconciliation – test – Control totals tie to the trial balance\nControl totals – test – Extracts follow the agreed file layout\nTake-over accounting – test – Cleansing backlog is clear before the freeze\nDefect tracking – test – Rollback is rehearsed\nData-owner sign-off – test – The go/no-go pack is complete","milestones":"2026-01-20 – Business case approved\n2026-03-16 – Target platform scope signed\n2026-10-04 – Mock 1 static and financial run\n2026-09-28 – Regulatory report-line map signed\n2026-11-14 – Mock 2 static data\n2026-12-07 – Integration SIT entry\n2027-01-29 – Access recertification complete\n2027-01-16 – Mock 3 financial reconciliation\n2027-03-06 – Dress rehearsal\n2027-05-10 – Go-live and hypercare exit","dependencies":"Source access granted\nFile layout signed\nTake-over accounts opened\nData owners named\nMock calendar held\nTrial balance owner named\nDefect severity scale agreed\nRollback steps written\nDress rehearsal environment booked\nRetention schedule agreed with records management","estimated_investment":6100000,"funding_sources":"Programme budget\nBusiness area budget\nShared technology fund\nTraining budget\nHypercare contingency\nEnvironment capacity\nMigration partner statement of work\nTesting partner statement of work\nNo new capital request in this slice\nBenefits tracked by finance","review_cadence":"monthly","kpis":"Mock 2 static data loads inside the window\nMock 3 financial data reconciles\nDress rehearsal finishes with no severity-1 defect open\nTake-over and suspense accounts are zero\nEach population has a named data owner\nControl totals tie to the trial balance\nExtracts follow the agreed file layout\nCleansing backlog is clear before the freeze\nRollback is rehearsed\nThe go/no-go pack is complete","risks_mitigations":"Take-over accounts do not return to zero – Keep three mocks plus one dress rehearsal\nA source access request is still open at Mock 2 – Book the dress rehearsal environment\nCleansing slips past the freeze – Issue the remaining data-owner sign-off forms\nThe file layout changes late – Add the defect scale to the mock entry checklist\nA severity-1 defect is found in dress rehearsal – Remove the customer sample from the shared workbook\nControl totals are taken before close of business – Confirm extracts are after close of business\nData owners are unavailable to sign – Hold the file layout after Mock 2\nThe mock window overruns – Name the trial balance owner\nPersonal data is copied into a shared workbook – Write rollback as steps, not an outline\nRollback is untested – Confirm cleansing stays in the source","roles_and_responsibilities":"Delivery lead – Priya Naidoo\nBusiness data owner – Amina Diallo\nExecutive sponsor – Olivia Banda\nTechnical lead – Brian Otieno\nReconciliation lead – Olivia Banda\nFinance partner – Daniel Okafor\nTest lead – Catherine Mwangi\nQuality lead – Nadia Rahman\nChange lead – Linda Zhou\nMigration analyst – Ahmed Hassan","glossary":"Alternate key\tThe legacy reference kept so old numbers remain searchable\nFreeze\tThe point after which the legacy core takes no new business\nTake-over account\tThe account that receives migrated balances and must return to zero\nMock\tA full practice load used to prove the migration\nDress rehearsal\tThe final practice on a production-like path\nHypercare\tThe staffed support period after go-live\nSurvivor\tThe customer record kept when duplicates are merged\nPopulation\tThe set of records a data owner signs\nControl total\tThe figure the load must match, usually from the trial balance\nReadiness\tThe signed statement that a slice can enter the next stage","appendices":"Appendix 1\tSource profiling\nAppendix 2\tExtraction from both legacy instances\nAppendix 3\tCleansing at source\nAppendix 4\tTransformation rules\nAppendix 5\tMock runs\nAppendix 6\tDress rehearsal\nAppendix 7\tReconciliation by product and currency\nAppendix 8\tTake-over and suspense accounts\nAppendix 9\tControl totals\nAppendix 10\tBusiness sign-off of each population","version_history":"0.9\t2026-11-06\tPriya Naidoo\tSample baseline for the Northbridge programme","related_documents":"Technology delivery overview for this slice\nData migration strategy\nInterface register\nOperational readiness notes\nGo-live pack"}$j$),
  ('00000000-0000-4000-a01a-000000000006', '00000000-0000-4000-9003-000000000002', 'Integration and interfaces roadmap', 'Two-year roadmap for Integration and interfaces on the Northbridge Bank technology programme. Owner: Ravi Pillai.', 'draft', $j${"document_reference":"NRB-RM-06","document_version":"0.9","document_owner":"Brian Otieno","next_review_date":"2026-11-19","roadmap_owner":"Ravi Pillai","horizon":"2_years","roadmap_start":"2026-06-01","purpose":"Delivery of the interfaces the target platform needs from channels, cards, finance, documents and the user store. Owner: Brian Otieno.","objectives":"Each in-scope interface has a contract, a test and an owner\nFailed messages are visible on one dashboard\nCard status cross-check agrees active cards\nTrial-balance file balances before it is used\nImage retrieval works for a mandate\nChannels no longer call the legacy cores after go-live\nRepair time for a failed message is under 30 minutes\nCertificates are valid through hypercare\nNo silent message loss in dress rehearsal\nInterface owners sign readiness","scope":"Internet banking interface\nMobile banking interface\nBranch teller interface\nContact centre interface\nCard status cross-check\nDocument image retrieval\nFinance trial-balance file\nDigital user-store link\nNotification dispatch\nInterface monitoring and repair","out_of_scope":"A new integration platform product selection\nOpen-banking directory build\nCard scheme certification\nATM switch replacement\nPoint of sale acquiring\nMarket data feed\nPayroll interface\nBuilding access systems\nA general enterprise service bus rebuild\nPartner onboarding portal","assumptions":"Existing channels are reused and pointed at the target\nThe card system is not migrated; only status is cross-checked\nThe finance system stays and sends a file\nCertificates can be renewed without a scheme change\nOne dashboard covers every in-scope interface\nMessage replay is allowed once\nOwners are named before SIT\nTest data is synthetic except for the dress rehearsal\nThe legacy cores stay up read-only after go-live\nNo new interface is added after design approval","constraints":"SIT entry dates are fixed on the integration plan\nA missing certificate blocks that interface\nCard numbers are not stored on the dashboard\nThe trial-balance file is after close of business\nReplay cannot create a second payment\nPersonal images are retrieved only for an entitled user\nThe dress rehearsal uses the production-like path\nRepair is dual-controlled for payments\nMonitoring alerts reach the duty roster\nHypercare keeps the same dashboard","vision":"Northbridge Bank runs integration and interfaces on the target platform after the April 2027 weekend, with the legacy cores read-only.","business_drivers":"Channels call one platform\nFailed messages are seen, not lost\nCard status stays consistent\nFinance receives a file it can tie\nBranches can see a mandate\nLess overnight manual checking\nCertificates are tracked\nA readiness sign-off per interface\nRepair in one queue\nA cleaner decommission of the legacy cores","principles":"One owner for the population\nCleanse in the source\nKeep an alternate key for the legacy reference\nNo new tool unless the existing one cannot do the job\nRehearse before the weekend\nSign-off is by the business owner\nPersonal data stays in the residency region\nA red item is visible on the overview\nEvidence is kept for the retention period\nVendor-neutral names in every artefact","current_technologies":"Target platform\nInternet banking\nMobile banking\nBranch teller\nContact centre\nCard management platform\nDocument imaging system\nFinance system\nDigital user store\nNotification service","constraints_and_issues":"Card status and trial-balance have no SIT slot\nCertificate inventory is incomplete\nDashboard shows four of twelve interfaces\nRepair role for payments is not named\nImage retrieval test used a synthetic mandate only\nOne channel configuration still has the legacy address\nDuty roster stops at go-live and not hypercare\nMessage sample for notifications is unsigned\nReplay test has not been run\nThe interface register and this delivery use different names for two flows","initiatives":"Channel interface – build – Each in-scope interface has a contract, a test and an owner\nCard status cross-check – build – Failed messages are visible on one dashboard\nImage retrieval – build – Card status cross-check agrees active cards\nTrial-balance file – build – Trial-balance file balances before it is used\nUser-store link – build – Image retrieval works for a mandate\nNotification dispatch – build – Channels no longer call the legacy cores after go-live\nMessage repair – build – Repair time for a failed message is under 30 minutes\nInterface monitoring – build – Certificates are valid through hypercare\nCertificate management – build – No silent message loss in dress rehearsal\nReadiness sign-off – build – Interface owners sign readiness","milestones":"2026-01-20 – Business case approved\n2026-03-16 – Target platform scope signed\n2026-10-04 – Mock 1 static and financial run\n2026-09-28 – Regulatory report-line map signed\n2026-11-14 – Mock 2 static data\n2026-12-07 – Integration SIT entry\n2027-01-29 – Access recertification complete\n2027-01-16 – Mock 3 financial reconciliation\n2027-03-06 – Dress rehearsal\n2027-05-10 – Go-live and hypercare exit","dependencies":"Interface contracts approved\nSIT slots booked\nCertificates inventoried\nDashboard built\nRepair roles assigned\nCard status file sample received\nTrial-balance file sample received\nImage retrieval entitlement model agreed\nDuty roster published\nDress rehearsal path agreed","estimated_investment":3700000,"funding_sources":"Programme budget\nBusiness area budget\nShared technology fund\nTraining budget\nHypercare contingency\nEnvironment capacity\nMigration partner statement of work\nTesting partner statement of work\nNo new capital request in this slice\nBenefits tracked by finance","review_cadence":"monthly","kpis":"Each in-scope interface has a contract, a test and an owner\nFailed messages are visible on one dashboard\nCard status cross-check agrees active cards\nTrial-balance file balances before it is used\nImage retrieval works for a mandate\nChannels no longer call the legacy cores after go-live\nRepair time for a failed message is under 30 minutes\nCertificates are valid through hypercare\nNo silent message loss in dress rehearsal\nInterface owners sign readiness","risks_mitigations":"Two interfaces miss their SIT slot – Book SIT slots for card status and the trial-balance file\nA certificate expires in hypercare – Finish the certificate inventory\nCard status file is late – Name the payments repair role\nTrial-balance file does not balance – Extend the duty roster through hypercare\nReplay creates a duplicate payment – Remove the remaining legacy channel address\nThe dashboard misses a silent failure – Align the two flow names with the interface register\nImage retrieval is too slow at the branch – Sign the notification message sample\nA channel still points at the legacy core – Run the replay test before SIT exit\nRepair roles are not staffed at night – Agree the image entitlement model\nA new interface is added after design approval – Hold the interface list after design approval","roles_and_responsibilities":"Delivery lead – Brian Otieno\nBusiness owner – Ravi Pillai\nExecutive sponsor – Daniel Okafor\nTechnical lead – Ravi Pillai\nInterface analyst – Priya Naidoo\nTest lead – Catherine Mwangi\nSecurity partner – Nadia Rahman\nOperations lead – Linda Zhou\nFinance partner – Olivia Banda\nChange lead – Amina Diallo","glossary":"Alternate key\tThe legacy reference kept so old numbers remain searchable\nFreeze\tThe point after which the legacy core takes no new business\nTake-over account\tThe account that receives migrated balances and must return to zero\nMock\tA full practice load used to prove the migration\nDress rehearsal\tThe final practice on a production-like path\nHypercare\tThe staffed support period after go-live\nSurvivor\tThe customer record kept when duplicates are merged\nPopulation\tThe set of records a data owner signs\nControl total\tThe figure the load must match, usually from the trial balance\nReadiness\tThe signed statement that a slice can enter the next stage","appendices":"Appendix 1\tInternet banking interface\nAppendix 2\tMobile banking interface\nAppendix 3\tBranch teller interface\nAppendix 4\tContact centre interface\nAppendix 5\tCard status cross-check\nAppendix 6\tDocument image retrieval\nAppendix 7\tFinance trial-balance file\nAppendix 8\tDigital user-store link\nAppendix 9\tNotification dispatch\nAppendix 10\tInterface monitoring and repair","version_history":"0.9\t2026-11-05\tBrian Otieno\tSample baseline for the Northbridge programme","related_documents":"Technology delivery overview for this slice\nData migration strategy\nInterface register\nOperational readiness notes\nGo-live pack"}$j$),
  ('00000000-0000-4000-a01a-000000000007', '00000000-0000-4000-9003-000000000002', 'Cybersecurity and access roadmap', 'Two-year roadmap for Cybersecurity and access on the Northbridge Bank technology programme. Owner: Nadia Rahman.', 'draft', $j${"document_reference":"NRB-RM-07","document_version":"0.9","document_owner":"Nadia Rahman","next_review_date":"2026-11-24","roadmap_owner":"Nadia Rahman","horizon":"2_years","roadmap_start":"2026-06-15","purpose":"Delivery of user access, recertification and the security controls required before go-live. Currently on hold. Owner: Nadia Rahman.","objectives":"Every loaded user has a recertified entitlement\nLeavers are absent from the load\nPrivileged access is listed and approved\nStaff can sign in on day one\nLogging meets the agreed control\nAudit can see who approved each role\nHypercare can revoke access the same day\nNo shared user identities\nRecertification finishes before the freeze\nThe security owner signs readiness","scope":"Bank user profiles\nUser groups and roles\nLine-manager recertification\nPrivileged access\nJoiner, mover and leaver handling\nAuthentication for staff\nEntitlement after go-live\nSecurity logging\nAccess evidence for audit\nHypercare access revocation","out_of_scope":"Customer authentication redesign\nA new identity product selection\nBuilding access\nCard PIN platform\nEndpoint replacement\nSecurity operations centre build\nPenetration test of unrelated systems\nData loss prevention product selection\nSupplier security assessments outside this programme\nStaff background checks","assumptions":"Line managers recertify their own staff\nThe identity directory is a source, not a system being replaced\nPrivileged access is a separate list\nLeavers are removed in the source before extract\nCustomer sign-in is owned by the channels delivery\nLogging uses the target platform capability\nEvidence is a record of the approval, not a screenshot folder\nThe hold ends only when a recertification date is set\nNo shared identities are created for go-live\nHypercare revocation uses the same process as business as usual","constraints":"User load cannot start before recertification\nThe freeze date does not move for this workstream alone\nPrivileged access requires two approvers\nPersonal data in access logs follows the retention schedule\nA leaver cannot be loaded\nShared identities are prohibited\nThe hold is visible on the programme overview\nDesign does not restart without the sponsor\nEvidence is kept with the go-live pack\nCustomer credentials are out of this delivery","vision":"Northbridge Bank runs cybersecurity and access on the target platform after the April 2027 weekend, with the legacy cores read-only.","business_drivers":"Users loaded are users the bank still wants\nLeavers do not keep access\nPrivileged access is visible\nAudit can see the approval\nStaff sign in on day one\nRevocation does not wait for a ticket queue\nA clear hold rather than a hidden slip\nLess argument at go-live about who approved a role\nLogging that matches the agreed control\nA security owner signature on the pack","principles":"One owner for the population\nCleanse in the source\nKeep an alternate key for the legacy reference\nNo new tool unless the existing one cannot do the job\nRehearse before the weekend\nSign-off is by the business owner\nPersonal data stays in the residency region\nA red item is visible on the overview\nEvidence is kept for the retention period\nVendor-neutral names in every artefact","current_technologies":"Identity and access management directory\nTarget platform access\nLine-manager workflow\nPrivileged access register\nSecurity logging\nStaff directory\nAudit evidence store\nService desk\nHypercare roster\nGo-live pack","constraints_and_issues":"No recertification date is in the plan\nThe workstream is on hold\nPrivileged role list is a draft from the legacy core\nLeaver extract definition is not written\nLogging requirements are not signed\nTwo line-manager areas have no named manager\nThe hold was not reflected on the previous overview\nEvidence template is blank\nService desk revocation process is the legacy one\nRestart criteria are not written down","initiatives":"User profile load – design – Every loaded user has a recertified entitlement\nRole recertification – design – Leavers are absent from the load\nPrivileged access list – design – Privileged access is listed and approved\nLeaver removal – design – Staff can sign in on day one\nStaff sign-in – design – Logging meets the agreed control\nSecurity logging – design – Audit can see who approved each role\nApproval evidence – design – Hypercare can revoke access the same day\nSame-day revocation – design – No shared user identities\nAccess enquiry – design – Recertification finishes before the freeze\nReadiness sign-off – design – The security owner signs readiness","milestones":"2026-01-20 – Business case approved\n2026-03-16 – Target platform scope signed\n2026-10-04 – Mock 1 static and financial run\n2026-09-28 – Regulatory report-line map signed\n2026-11-14 – Mock 2 static data\n2026-12-07 – Integration SIT entry\n2027-01-29 – Access recertification complete\n2027-01-16 – Mock 3 financial reconciliation\n2027-03-06 – Dress rehearsal\n2027-05-10 – Go-live and hypercare exit","dependencies":"Recertification date agreed\nLine-manager list confirmed\nPrivileged roles listed\nLeaver extract defined\nLogging requirements signed\nEvidence template agreed\nService desk process for revocation\nSponsor accepts the restart criteria\nChannels delivery owns customer sign-in\nFreeze date reconfirmed","estimated_investment":1900000,"funding_sources":"Programme budget\nBusiness area budget\nShared technology fund\nTraining budget\nHypercare contingency\nEnvironment capacity\nMigration partner statement of work\nTesting partner statement of work\nNo new capital request in this slice\nBenefits tracked by finance","review_cadence":"quarterly","kpis":"Every loaded user has a recertified entitlement\nLeavers are absent from the load\nPrivileged access is listed and approved\nStaff can sign in on day one\nLogging meets the agreed control\nAudit can see who approved each role\nHypercare can revoke access the same day\nNo shared user identities\nRecertification finishes before the freeze\nThe security owner signs readiness","risks_mitigations":"Recertification has no date and the user load misses the freeze – Set a recertification date or keep the hold\nLeavers are loaded – Write the restart criteria\nA shared identity is created to save time – Name the two missing line managers\nPrivileged access is copied unchanged – Sign the logging requirements\nLogging is weaker than the agreed control – Define the leaver extract\nLine managers do not complete recertification – Replace the draft privileged-role list\nThe hold hides other security work that could continue – Confirm customer sign-in sits with channels\nEvidence is not audit-ready – Adopt an evidence template\nCustomer sign-in is assumed to be in this delivery – Update the service desk revocation process\nHypercare cannot revoke on the day – Show the hold on the programme overview","roles_and_responsibilities":"Delivery lead – Nadia Rahman\nBusiness owner – Daniel Okafor\nExecutive sponsor – Grace Moyo\nTechnical lead – Nadia Rahman\nAccess analyst – Ravi Pillai\nAudit partner – Olivia Banda\nService desk lead – Linda Zhou\nChange lead – Amina Diallo\nTest lead – Catherine Mwangi\nRisk partner – Joy Akinyi","glossary":"Alternate key\tThe legacy reference kept so old numbers remain searchable\nFreeze\tThe point after which the legacy core takes no new business\nTake-over account\tThe account that receives migrated balances and must return to zero\nMock\tA full practice load used to prove the migration\nDress rehearsal\tThe final practice on a production-like path\nHypercare\tThe staffed support period after go-live\nSurvivor\tThe customer record kept when duplicates are merged\nPopulation\tThe set of records a data owner signs\nControl total\tThe figure the load must match, usually from the trial balance\nReadiness\tThe signed statement that a slice can enter the next stage","appendices":"Appendix 1\tBank user profiles\nAppendix 2\tUser groups and roles\nAppendix 3\tLine-manager recertification\nAppendix 4\tPrivileged access\nAppendix 5\tJoiner, mover and leaver handling\nAppendix 6\tAuthentication for staff\nAppendix 7\tEntitlement after go-live\nAppendix 8\tSecurity logging\nAppendix 9\tAccess evidence for audit\nAppendix 10\tHypercare access revocation","version_history":"0.9\t2026-10-20\tNadia Rahman\tSample baseline for the Northbridge programme","related_documents":"Technology delivery overview for this slice\nData migration strategy\nInterface register\nOperational readiness notes\nGo-live pack"}$j$),
  ('00000000-0000-4000-a01a-000000000008', '00000000-0000-4000-9003-000000000002', 'Environments and release roadmap', 'Two-year roadmap for Environments and release on the Northbridge Bank technology programme. Owner: Ravi Pillai.', 'draft', $j${"document_reference":"NRB-RM-08","document_version":"0.9","document_owner":"Ravi Pillai","next_review_date":"2026-11-18","roadmap_owner":"Ravi Pillai","horizon":"2_years","roadmap_start":"2026-03-16","purpose":"Delivery of the environment path from development through dress rehearsal, production and recovery, and the release calendar that uses it. Owner: Ravi Pillai.","objectives":"Every test stage has a booked environment\nDress rehearsal uses a production-like path\nRefresh is requested and logged\nThe release calendar is the only source of release dates\nRecovery is restored and checked before go-live\nNo two mocks share an environment\nProduction runbook is rehearsed\nAccess to production-like data is approved\nBooking clashes are visible\nThe forum signs environment readiness","scope":"Development environment\nTest environment\nSystem integration environment\nUser acceptance environment\nPre-production\nProduction cutover runbook\nRecovery environment\nRelease calendar\nData refresh request\nEnvironment booking","out_of_scope":"A new data centre build\nEnd-user device replacement\nNetwork redesign\nCloud provider selection\nProduction support model\nMonitoring product selection\nStaff laptop build\nBranch hardware\nPrint room\nArchive hardware","assumptions":"Existing hosting is reused\nProduction-like data is masked except in dress rehearsal under approval\nOne calendar is enough\nRecovery is a restore test, not a second data centre project\nTeams will book if the booking is easier than asking in a chat\nThe April weekend is reserved now\nRefreshes happen outside test execution\nThe forum can refuse a clash\nRunbooks are steps, not slides\nHypercare uses the production environment","constraints":"The dress rehearsal date is fixed once booked\nMasked data is the default\nProduction access is named people only\nTwo mocks cannot share an environment\nA refresh during execution is refused\nRecovery test evidence is kept\nThe calendar is not a side spreadsheet\nThe April weekend is not used for another release\nBooking is mandatory from SIT onward\nRunbook steps are followed in the rehearsal","vision":"Northbridge Bank runs environments and release on the target platform after the April 2027 weekend, with the legacy cores read-only.","business_drivers":"Tests are not stopped by a clash\nDress rehearsal looks like production\nRefreshes are traceable\nOne calendar for the programme\nA recovery test before it is needed\nLess unmasked data in test\nNamed production access\nA runbook that was actually followed\nCapacity planned rather than discovered\nA signed environment path","principles":"One owner for the population\nCleanse in the source\nKeep an alternate key for the legacy reference\nNo new tool unless the existing one cannot do the job\nRehearse before the weekend\nSign-off is by the business owner\nPersonal data stays in the residency region\nA red item is visible on the overview\nEvidence is kept for the retention period\nVendor-neutral names in every artefact","current_technologies":"Development environment\nTest environment\nSystem integration environment\nUser acceptance environment\nPre-production\nProduction\nRecovery environment\nBooking register\nRelease calendar\nRunbook store","constraints_and_issues":"Dress rehearsal environment is not booked\nRefresh is still a manual copy\nMasking rules are drafted and not approved\nThe release calendar is a spreadsheet as well as the register\nRecovery restore has not been attempted\nTwo teams have asked for SIT on the same week\nProduction access list is not written\nRunbook template is agreed\nApril weekend is reserved\nBooking is optional in test and mandatory only from SIT","initiatives":"Environment booking – build – Every test stage has a booked environment\nData refresh – build – Dress rehearsal uses a production-like path\nRelease calendar – build – Refresh is requested and logged\nMasked data – build – The release calendar is the only source of release dates\nDress rehearsal path – build – Recovery is restored and checked before go-live\nProduction runbook – build – No two mocks share an environment\nRecovery restore – build – Production runbook is rehearsed\nAccess approval – build – Access to production-like data is approved\nClash detection – build – Booking clashes are visible\nReadiness sign-off – build – The forum signs environment readiness","milestones":"2026-01-20 – Business case approved\n2026-03-16 – Target platform scope signed\n2026-10-04 – Mock 1 static and financial run\n2026-09-28 – Regulatory report-line map signed\n2026-11-14 – Mock 2 static data\n2026-12-07 – Integration SIT entry\n2027-01-29 – Access recertification complete\n2027-01-16 – Mock 3 financial reconciliation\n2027-03-06 – Dress rehearsal\n2027-05-10 – Go-live and hypercare exit","dependencies":"Hosting capacity confirmed\nMasking approach agreed\nApril weekend reserved\nDress rehearsal slot requested\nRefresh process written\nBooking register available\nRecovery backup identifiable\nNamed production access list\nRelease calendar owner named\nRunbook template agreed","estimated_investment":2200000,"funding_sources":"Programme budget\nBusiness area budget\nShared technology fund\nTraining budget\nHypercare contingency\nEnvironment capacity\nMigration partner statement of work\nTesting partner statement of work\nNo new capital request in this slice\nBenefits tracked by finance","review_cadence":"monthly","kpis":"Every test stage has a booked environment\nDress rehearsal uses a production-like path\nRefresh is requested and logged\nThe release calendar is the only source of release dates\nRecovery is restored and checked before go-live\nNo two mocks share an environment\nProduction runbook is rehearsed\nAccess to production-like data is approved\nBooking clashes are visible\nThe forum signs environment readiness","risks_mitigations":"Dress rehearsal has no environment – Book the dress rehearsal environment\nA refresh uses unmasked production data – Approve the masking rules\nTwo mocks are booked on one environment – Retire the side spreadsheet\nThe April weekend is double-booked – Write the production access list\nRecovery backup cannot be restored – Schedule the recovery restore\nTeams bypass the calendar – Refuse the SIT clash\nProduction access is wider than the named list – Keep refresh out of execution windows\nRunbook steps are skipped in rehearsal – Confirm the April weekend reservation\nCapacity runs out before UAT – Make booking mandatory from SIT\nA refresh lands during execution – Name the calendar owner","roles_and_responsibilities":"Delivery lead – Ravi Pillai\nBusiness owner – Brian Otieno\nExecutive sponsor – Daniel Okafor\nTechnical lead – Ravi Pillai\nEnvironment analyst – Priya Naidoo\nRelease manager – Linda Zhou\nSecurity partner – Nadia Rahman\nTest lead – Catherine Mwangi\nOperations lead – Ahmed Hassan\nChange lead – Amina Diallo","glossary":"Alternate key\tThe legacy reference kept so old numbers remain searchable\nFreeze\tThe point after which the legacy core takes no new business\nTake-over account\tThe account that receives migrated balances and must return to zero\nMock\tA full practice load used to prove the migration\nDress rehearsal\tThe final practice on a production-like path\nHypercare\tThe staffed support period after go-live\nSurvivor\tThe customer record kept when duplicates are merged\nPopulation\tThe set of records a data owner signs\nControl total\tThe figure the load must match, usually from the trial balance\nReadiness\tThe signed statement that a slice can enter the next stage","appendices":"Appendix 1\tDevelopment environment\nAppendix 2\tTest environment\nAppendix 3\tSystem integration environment\nAppendix 4\tUser acceptance environment\nAppendix 5\tPre-production\nAppendix 6\tProduction cutover runbook\nAppendix 7\tRecovery environment\nAppendix 8\tRelease calendar\nAppendix 9\tData refresh request\nAppendix 10\tEnvironment booking","version_history":"0.9\t2026-11-04\tRavi Pillai\tSample baseline for the Northbridge programme","related_documents":"Technology delivery overview for this slice\nData migration strategy\nInterface register\nOperational readiness notes\nGo-live pack"}$j$),
  ('00000000-0000-4000-a01a-000000000009', '00000000-0000-4000-9003-000000000002', 'Operational readiness and hypercare roadmap', 'Two-year roadmap for Operational readiness and hypercare on the Northbridge Bank technology programme. Owner: Ahmed Hassan.', 'draft', $j${"document_reference":"NRB-RM-09","document_version":"0.9","document_owner":"Linda Zhou","next_review_date":"2026-11-20","roadmap_owner":"Ahmed Hassan","horizon":"2_years","roadmap_start":"2026-09-01","purpose":"Delivery of the support model, runbooks, monitoring handover and the hypercare period after go-live. Owner: Linda Zhou.","objectives":"Every cutover step has a runbook someone has walked through\nHypercare shifts are named, including nights\nThe daily bridge has an agenda and a chair\nSeverity scale matches the defect scale\nMonitoring alerts reach the roster\nKnown errors are written down before go-live\nExit criteria are numeric\nA business-as-usual owner is named\nStaff know who to call\nThe sponsor agrees the exit","scope":"Support model\nRunbooks for the cutover weekend\nHypercare roster\nDaily hypercare bridge\nSeverity scale for hypercare\nMonitoring handover\nKnown-error list\nExit criteria from hypercare\nBusiness-as-usual owner\nStaff communications","out_of_scope":"A new service-desk product\nBranch refurbishment\nA 24-hour contact centre build\nVendor contract renegotiation\nProduction data centre build\nCustomer advertising campaign\nStaff bonus scheme\nLong-term capacity management\nA new major incident process for the whole bank\nDecommission of the legacy cores","assumptions":"Hypercare lasts four weeks\nThe existing service desk is the front door\nRunbooks are steps with an expected result\nNight shifts are required for the first week only\nMonitoring is handed over, not rebuilt\nExit is agreed by the sponsor, not assumed at day 28\nBusiness-as-usual owners are the product owners\nCommunications use the existing branch channel\nThe defect scale is reused\nDecommission is a later decision","constraints":"Hypercare cannot be staffed by unnamed roles\nA runbook that has not been walked through does not count\nThe first week has night cover\nExit criteria are set before go-live\nThe bridge is every business day in hypercare\nSeverity 1 has a 30-minute response\nCustomer communications during an incident use the agreed template\nThe service desk is not replaced\nThe roster is published two weeks before dress rehearsal\nBusiness-as-usual ownership starts only after exit","vision":"Northbridge Bank runs operational readiness and hypercare on the target platform after the April 2027 weekend, with the legacy cores read-only.","business_drivers":"A weekend someone has already rehearsed\nNamed people on the night shift\nCustomers reach a desk that has a script\nAlerts that reach a person\nA known end to hypercare\nProduct owners who take the service back\nLess dependence on the project team after exit\nStaff who know who to call\nEvidence that the runbook was used\nA calmer first month","principles":"One owner for the population\nCleanse in the source\nKeep an alternate key for the legacy reference\nNo new tool unless the existing one cannot do the job\nRehearse before the weekend\nSign-off is by the business owner\nPersonal data stays in the residency region\nA red item is visible on the overview\nEvidence is kept for the retention period\nVendor-neutral names in every artefact","current_technologies":"Service desk\nMonitoring dashboard\nRunbook store\nRoster\nBridge conference\nKnown-error list\nBranch communications\nTarget platform\nIncident log\nGo-live pack","constraints_and_issues":"Support model is not drafted\nNo runbook exists yet\nNight shifts are unnamed\nMonitoring owner is not named\nBridge chair is not named\nExit criteria are not drafted\nThe forum meets monthly, which is light for the time left\nService desk script is the legacy script\nKnown-error list does not exist\nBusiness-as-usual owners are assumed, not confirmed","initiatives":"Support model – initiation – Every cutover step has a runbook someone has walked through\nCutover runbook – initiation – Hypercare shifts are named, including nights\nHypercare roster – initiation – The daily bridge has an agenda and a chair\nDaily bridge – initiation – Severity scale matches the defect scale\nSeverity handling – initiation – Monitoring alerts reach the roster\nMonitoring handover – initiation – Known errors are written down before go-live\nKnown errors – initiation – Exit criteria are numeric\nExit criteria – initiation – A business-as-usual owner is named\nStaff communication – initiation – Staff know who to call\nBusiness-as-usual handover – initiation – The sponsor agrees the exit","milestones":"2026-01-20 – Business case approved\n2026-03-16 – Target platform scope signed\n2026-10-04 – Mock 1 static and financial run\n2026-09-28 – Regulatory report-line map signed\n2026-11-14 – Mock 2 static data\n2026-12-07 – Integration SIT entry\n2027-01-29 – Access recertification complete\n2027-01-16 – Mock 3 financial reconciliation\n2027-03-06 – Dress rehearsal\n2027-05-10 – Go-live and hypercare exit","dependencies":"Support model drafted\nRunbook template agreed\nRoster owners identified\nMonitoring owner named\nSeverity scale reused from defects\nBridge chair named\nExit criteria drafted\nBranch communication channel confirmed\nDress rehearsal date known\nSponsor available for the exit decision","estimated_investment":1500000,"funding_sources":"Programme budget\nBusiness area budget\nShared technology fund\nTraining budget\nHypercare contingency\nEnvironment capacity\nMigration partner statement of work\nTesting partner statement of work\nNo new capital request in this slice\nBenefits tracked by finance","review_cadence":"quarterly","kpis":"Every cutover step has a runbook someone has walked through\nHypercare shifts are named, including nights\nThe daily bridge has an agenda and a chair\nSeverity scale matches the defect scale\nMonitoring alerts reach the roster\nKnown errors are written down before go-live\nExit criteria are numeric\nA business-as-usual owner is named\nStaff know who to call\nThe sponsor agrees the exit","risks_mitigations":"Night shifts stay unnamed – Draft the support model before December\nRunbooks are written and never walked through – Name the bridge chair\nHypercare is assumed to end on day 28 – Name night-shift leads for week one\nMonitoring alerts go to a mailbox nobody reads – Name the monitoring owner\nThe service desk has no script – Confirm product owners as the business-as-usual owners\nSeverity 1 response is slower than 30 minutes – Draft exit criteria as numbers\nStaff call the project instead of the desk – Increase the forum to fortnightly from January\nKnown errors are discovered by customers – Replace the service desk script\nThe sponsor is unavailable for exit – Open a known-error list\nDecommission is started during hypercare – Keep decommission out of hypercare","roles_and_responsibilities":"Delivery lead – Linda Zhou\nBusiness owner – Catherine Mwangi\nExecutive sponsor – Grace Moyo\nTechnical lead – Ahmed Hassan\nService desk lead – Brian Otieno\nOperations lead – Ravi Pillai\nChange lead – Amina Diallo\nMonitoring analyst – Priya Naidoo\nCommunications lead – Nomvula Khumalo\nRisk partner – Nadia Rahman","glossary":"Alternate key\tThe legacy reference kept so old numbers remain searchable\nFreeze\tThe point after which the legacy core takes no new business\nTake-over account\tThe account that receives migrated balances and must return to zero\nMock\tA full practice load used to prove the migration\nDress rehearsal\tThe final practice on a production-like path\nHypercare\tThe staffed support period after go-live\nSurvivor\tThe customer record kept when duplicates are merged\nPopulation\tThe set of records a data owner signs\nControl total\tThe figure the load must match, usually from the trial balance\nReadiness\tThe signed statement that a slice can enter the next stage","appendices":"Appendix 1\tSupport model\nAppendix 2\tRunbooks for the cutover weekend\nAppendix 3\tHypercare roster\nAppendix 4\tDaily hypercare bridge\nAppendix 5\tSeverity scale for hypercare\nAppendix 6\tMonitoring handover\nAppendix 7\tKnown-error list\nAppendix 8\tExit criteria from hypercare\nAppendix 9\tBusiness-as-usual owner\nAppendix 10\tStaff communications","version_history":"0.9\t2026-10-15\tLinda Zhou\tSample baseline for the Northbridge programme","related_documents":"Technology delivery overview for this slice\nData migration strategy\nInterface register\nOperational readiness notes\nGo-live pack"}$j$),
  ('00000000-0000-4000-a01a-00000000000a', '00000000-0000-4000-9003-000000000002', 'Regulatory reporting roadmap', 'Two-year roadmap for Regulatory reporting on the Northbridge Bank technology programme. Owner: Priya Naidoo.', 'draft', $j${"document_reference":"NRB-RM-10","document_version":"0.9","document_owner":"Olivia Banda","next_review_date":"2027-03-31","roadmap_owner":"Priya Naidoo","horizon":"2_years","roadmap_start":"2026-02-02","purpose":"Completed delivery of the report-line mapping that lets finance keep the existing reporting tool across the migration. Owner: Olivia Banda.","objectives":"Every report line used in the last year has a mapped source\nThe mock cross-check agreed\nDifferences go to the agreed difference account\nThe financial controller has signed\nFinance did not change tool\nEvidence is in the go-live pack\nOwners are named\nThe guide is two pages\nReopen rule is written\nThe workstream is closed","scope":"Report-line map from the trial balance\nCurrency and company mapping\nFirst mock cross-check\nEvidence pack for finance\nNamed owner per report family\nDifference account treatment\nSign-off by the financial controller\nA reopen rule if a mapped line changes\nHandover to finance business as usual\nShort guide for the mapping","out_of_scope":"A new reporting tool\nPrudential return redesign\nTax engine replacement\nManagement information warehouse\nBoard pack redesign\nCost allocation rebuild\nAccount reconciliation product\nA new chart of accounts\nExternal audit tool\nReal-time finance dashboard","assumptions":"The finance system stays\nThe chart of accounts does not change for go-live\nLast year of report lines is the scope\nDifferences use account 14918 as already agreed for the journals\nThe controller is the signer\nA line that changes meaning reopens that report only\nThe guide is maintained by finance after handover\nNo new regulatory return is due before go-live\nCurrency codes are already harmonised enough for this map\nThe pack is evidence, not a new system","constraints":"No new reporting tool\nThe map cannot drop a line used in the last year\nDifferences have one account\nSign-off is the controller, not the project\nThe guide stays short\nPersonal customer data is not in the pack\nReopen does not restart the workstream\nThe September 2026 close stands\nHandover is to named finance owners\nThe April 2027 migration still uses this map","vision":"Finance keeps regulatory reporting in the existing tool, fed by the signed trial-balance map, through the April 2027 migration.","business_drivers":"Finance keeps a tool it already knows\nReport lines that still tie\nA signed map\nA small guide\nA reopen path that is narrow\nNo extra run cost for a new tool\nEvidence an auditor can read\nOwners who are named\nThe team freed for the financial mock\nA difference account that is already understood","principles":"One owner for the population\nCleanse in the source\nKeep an alternate key for the legacy reference\nNo new tool unless the existing one cannot do the job\nRehearse before the weekend\nSign-off is by the business owner\nPersonal data stays in the residency region\nA red item is visible on the overview\nEvidence is kept for the retention period\nVendor-neutral names in every artefact","current_technologies":"Finance and general ledger system\nReporting tool\nTrial balance\nMapping sheet\nEvidence store\nDifference account\nTarget take-over accounts\nGo-live pack\nFinance shared area\nController sign-off record","constraints_and_issues":"None open. The missed-line sample was corrected before sign-off\nThe first version of the guide was four pages and was cut\nOne company code was harmonised late and rechecked\nA draft pack page contained a customer sample and was removed\nThe controller signed version 1.1\nHandover meeting was held on 28 September 2026\nReopen rule is in the pack\nTwo owners were confirmed in writing\nThe September close is recorded\nThe team has stood down","initiatives":"Report-line map – closed – Every report line used in the last year has a mapped source\nCurrency mapping – closed – The mock cross-check agreed\nCompany mapping – closed – Differences go to the agreed difference account\nMock cross-check – closed – The financial controller has signed\nDifference account – closed – Finance did not change tool\nEvidence pack – closed – Evidence is in the go-live pack\nController sign-off – closed – Owners are named\nReopen rule – closed – The guide is two pages\nHandover – closed – Reopen rule is written\nShort guide – closed – The workstream is closed","milestones":"2026-01-20 – Business case approved\n2026-03-16 – Target platform scope signed\n2026-10-04 – Mock 1 static and financial run\n2026-09-28 – Regulatory report-line map signed\n2026-11-14 – Mock 2 static data\n2026-12-07 – Integration SIT entry\n2027-01-29 – Access recertification complete\n2027-01-16 – Mock 3 financial reconciliation\n2027-03-06 – Dress rehearsal\n2027-05-10 – Go-live and hypercare exit","dependencies":"Trial balance owner\nList of report lines from the last year\nDifference account agreed\nController availability\nMapping sheet tool\nEvidence store\nHarmonised currency codes\nCompany codes\nHandover meeting\nReopen rule drafted","estimated_investment":900000,"funding_sources":"Programme budget\nBusiness area budget\nShared technology fund\nTraining budget\nHypercare contingency\nEnvironment capacity\nMigration partner statement of work\nTesting partner statement of work\nNo new capital request in this slice\nBenefits tracked by finance","review_cadence":"quarterly","kpis":"Every report line used in the last year has a mapped source\nThe mock cross-check agreed\nDifferences go to the agreed difference account\nThe financial controller has signed\nFinance did not change tool\nEvidence is in the go-live pack\nOwners are named\nThe guide is two pages\nReopen rule is written\nThe workstream is closed","risks_mitigations":"A report line was missed – Close the workstream\nA mapped line changes meaning before April 2027 – Keep the reopen rule to a single report\nThe difference account is used for something else – Keep account 14918 as the difference account\nThe controller signature is on the wrong version – Leave the guide with finance\nThe guide is not kept – Do not select a new reporting tool\nA new return is announced – Accept version 1.1 as the signed map\nCurrency harmonisation is incomplete for one company – Remove customer-level rows from the pack\nThe pack holds customer-level data – Name two finance owners\nHandover owners leave – Use the map unchanged in April 2027 unless a line changes meaning\nThe workstream is treated as open and consumes the team – Stand the team down","roles_and_responsibilities":"Delivery lead – Olivia Banda\nBusiness owner – Olivia Banda\nExecutive sponsor – Grace Moyo\nTechnical lead – Priya Naidoo\nFinance analyst – Daniel Okafor\nMapping analyst – Amina Diallo\nAudit partner – Nadia Rahman\nTest lead – Catherine Mwangi\nChange lead – Linda Zhou\nRecords partner – Brian Otieno","glossary":"Alternate key\tThe legacy reference kept so old numbers remain searchable\nFreeze\tThe point after which the legacy core takes no new business\nTake-over account\tThe account that receives migrated balances and must return to zero\nMock\tA full practice load used to prove the migration\nDress rehearsal\tThe final practice on a production-like path\nHypercare\tThe staffed support period after go-live\nSurvivor\tThe customer record kept when duplicates are merged\nPopulation\tThe set of records a data owner signs\nControl total\tThe figure the load must match, usually from the trial balance\nReadiness\tThe signed statement that a slice can enter the next stage","appendices":"Appendix 1\tReport-line map from the trial balance\nAppendix 2\tCurrency and company mapping\nAppendix 3\tFirst mock cross-check\nAppendix 4\tEvidence pack for finance\nAppendix 5\tNamed owner per report family\nAppendix 6\tDifference account treatment\nAppendix 7\tSign-off by the financial controller\nAppendix 8\tA reopen rule if a mapped line changes\nAppendix 9\tHandover to finance business as usual\nAppendix 10\tShort guide for the mapping","version_history":"0.9\t2026-09-28\tOlivia Banda\tSample baseline for the Northbridge programme","related_documents":"Technology delivery overview for this slice\nData migration strategy\nInterface register\nOperational readiness notes\nGo-live pack"}$j$)
) AS v(id, register_id, title, description, status, field_values)
CROSS JOIN proj p
ON CONFLICT (id) DO NOTHING;

DO $$
DECLARE
  v_project UUID;
  v_overview INT;
  v_workstreams INT;
  v_milestones INT;
  v_roadmap INT;
BEGIN
  SELECT id INTO v_project FROM public.projects WHERE project_code = 'SEED334-PRJ-08' LIMIT 1;
  IF v_project IS NULL THEN
    RAISE NOTICE 'v1355: project SEED334-PRJ-08 not found — no seed rows inserted';
    RETURN;
  END IF;
  SELECT COUNT(*) INTO v_overview FROM public.local_register_records
    WHERE id::text LIKE '00000000-0000-4000-a017-%' AND record_project_id = v_project AND is_deleted = FALSE;
  SELECT COUNT(*) INTO v_workstreams FROM public.local_register_records
    WHERE id::text LIKE '00000000-0000-4000-a018-%' AND record_project_id = v_project AND is_deleted = FALSE;
  SELECT COUNT(*) INTO v_milestones FROM public.local_register_records
    WHERE id::text LIKE '00000000-0000-4000-a019-%' AND record_project_id = v_project AND is_deleted = FALSE;
  SELECT COUNT(*) INTO v_roadmap FROM public.local_register_records
    WHERE id::text LIKE '00000000-0000-4000-a01a-%' AND record_project_id = v_project AND is_deleted = FALSE;
  RAISE NOTICE 'v1355: overview % (expected 10), workstreams % (expected 10), milestones % (expected 10), roadmap % (expected 10)',
    v_overview, v_workstreams, v_milestones, v_roadmap;
END $$;
